  panel->RunActionsForTesting(base::ListValue().Append(base::DictValue().Set("tool","ask_user").Set("args",base::DictValue()
      .Set("question","Złożyć zamówienie za 129 zł?").Set("options",base::ListValue().Append("Tak").Append("Nie")))));
