IN_PROC_BROWSER_TEST_F(ZitterProfilesBrowserTest, AssistantBackgroundPageSharesProfileAndCanBeTakenOver) {
  const auto url=embedded_test_server()->GetURL("/storage_probe.html");
  ASSERT_TRUE(content::NavigateToURL(window_->contents("work"),url));
  ASSERT_TRUE(content::ExecJs(window_->contents("work"),"document.cookie='zitter_bg=shared; path=/'"));
  const size_t tabs=window_->tab_count("work");
  ASSERT_TRUE(window_->AssistantStartBackground("bg",{},url));
  auto* page=window_->assistant_background_for_testing("bg"); ASSERT_TRUE(page);
  EXPECT_EQ(window_->tab_count("work"),tabs);
  ASSERT_TRUE(content::WaitForLoadStop(page));
  // Same profile, same cookies: the background page is logged in like the user.
  EXPECT_EQ(page->GetBrowserContext(),window_->contents("work")->GetBrowserContext());
  EXPECT_EQ(content::EvalJs(page,"document.cookie.includes('zitter_bg=shared')"),true);
  ASSERT_TRUE(content::ExecJs(page,"document.body.innerHTML='<h1>Background work</h1><button onclick=\"document.title=\\'clicked\\'\">Pay</button>'"));
  AssistantPermissions allowed{true,true,true,false,false};
  base::test::TestFuture<base::Value> read;
  window_->AssistantTool("read_page",base::DictValue().Set("tab","@current"),allowed,read.GetCallback(),false,"bg");
  const auto* text=read.Get().GetDict().FindString("text"); ASSERT_TRUE(text);
  EXPECT_NE(text->find("Background work"),std::string::npos);
  std::string button;
  for(const auto& element:*read.Get().GetDict().FindList("elements"))if(*element.GetDict().FindString("tag")=="BUTTON")button=*element.GetDict().FindString("id");
  ASSERT_FALSE(button.empty());
  // Clicks still need native consent; the user's visible tabs stay read-only.
  base::test::TestFuture<base::Value> asked;
  window_->AssistantTool("click",base::DictValue().Set("tab","@current").Set("element",button).Set("confirmed",true),allowed,asked.GetCallback(),false,"bg");
  EXPECT_TRUE(asked.Get().GetDict().FindBool("confirmation_required").value_or(false));
  const auto visible=*window_->AssistantContext(allowed).FindList("tabs")->front().GetDict().FindString("mention");
  base::test::TestFuture<base::Value> refused;
  window_->AssistantTool("scroll",base::DictValue().Set("tab",visible).Set("dy",100),allowed,refused.GetCallback(),false,"bg");
  EXPECT_TRUE(refused.Get().GetDict().FindString("error"));
  base::test::TestFuture<base::Value> clicked;
  window_->AssistantTool("click",base::DictValue().Set("tab","@current").Set("element",button),allowed,clicked.GetCallback(),true,"bg");
  EXPECT_TRUE(clicked.Get().GetDict().FindBool("ok").value_or(false));
  EXPECT_EQ(content::EvalJs(page,"document.title"),"clicked");
  // Taking over makes it an ordinary, selected tab.
  ASSERT_TRUE(window_->AssistantTakeOver("bg"));
  EXPECT_EQ(window_->tab_count("work"),tabs+1);
  EXPECT_EQ(window_->contents("work"),page);
  EXPECT_FALSE(window_->assistant_background_for_testing("bg"));
  // A visible tab can move into the background, with its page state.
  ASSERT_TRUE(window_->AssistantStartBackground("moved","@current",GURL()));
  EXPECT_EQ(window_->assistant_background_for_testing("moved"),page);
  EXPECT_EQ(window_->tab_count("work"),tabs);
  EXPECT_NE(window_->contents("work"),page);
  window_->AssistantDiscardBackground("moved");
  EXPECT_FALSE(window_->assistant_background_for_testing("moved"));
}

// Ctrl+Tab walks tabs in the order they were used, not their sidebar order;
// the tab shown when Ctrl goes up becomes the most recent one.
IN_PROC_BROWSER_TEST_F(ZitterProfilesBrowserTest, NextTabFollowsRecentUse) {
  ASSERT_TRUE(window_->Select("work"));
  std::vector<content::WebContents*> pages{window_->contents("work")};
  for (int i = 0; i < 3; ++i) {
    ASSERT_TRUE(window_->NavigateFromBar(embedded_test_server()->GetURL("/storage_probe.html"), true));
    pages.push_back(window_->contents("work"));
  }
  ASSERT_EQ(4u, window_->tab_count("work"));
  // Use order: 0, then 3, then 1 (sidebar order stays 0 1 2 3).
  for (size_t index : {0u, 3u, 1u}) { window_->SelectTab(index); EXPECT_EQ(pages[index], window_->contents("work")); }
  auto settle = [] {
    base::RunLoop loop;  // Ctrl is up in tests: the cycle ends on its next check.
    base::SingleThreadTaskRunner::GetCurrentDefault()->PostDelayedTask(FROM_HERE, loop.QuitClosure(), base::Milliseconds(200));
    loop.Run();
  };
  ASSERT_TRUE(window_->RunShortcut("next_tab"));
  EXPECT_EQ(pages[3], window_->contents("work"));
  settle();
  // 3 is now the most recent, so the next press goes back to 1.
  ASSERT_TRUE(window_->RunShortcut("next_tab"));
  EXPECT_EQ(pages[1], window_->contents("work"));
  settle();
  ASSERT_TRUE(window_->RunShortcut("previous_tab"));
  // Backwards from 1: the least recently used tab, never shown in this run.
  EXPECT_EQ(pages[2], window_->contents("work"));
}

IN_PROC_BROWSER_TEST_F(ZitterProfilesBrowserTest, AssistantHideAndResize) {
  window_->ShowAssistant();auto* panel=window_->assistant();
  panel->Collapse();EXPECT_FALSE(panel->GetVisible());
  panel->Show();panel->SetPinned(true);panel->Collapse();EXPECT_TRUE(panel->GetVisible());
  panel->SetPinned(false);window_->widget()->LayoutRootViewIfNecessary();
  auto* grip=panel->resize_handle_for_testing();ASSERT_TRUE(grip);
  const int initial_width=panel->width();
  ui::MouseEvent press(ui::EventType::kMousePressed,gfx::Point(4,40),gfx::Point(4,40),base::TimeTicks::Now(),ui::EF_LEFT_MOUSE_BUTTON,ui::EF_LEFT_MOUSE_BUTTON);
  ASSERT_TRUE(grip->OnMousePressed(press));
  ui::MouseEvent drag(ui::EventType::kMouseDragged,gfx::Point(-76,40),gfx::Point(-76,40),base::TimeTicks::Now(),ui::EF_LEFT_MOUSE_BUTTON,0);
  ASSERT_TRUE(grip->OnMouseDragged(drag));
  EXPECT_GT(panel->width(),initial_width);
  ui::MouseEvent release(ui::EventType::kMouseReleased,gfx::Point(4,40),gfx::Point(4,40),base::TimeTicks::Now(),0,ui::EF_LEFT_MOUSE_BUTTON);
  grip->OnMouseReleased(release);
  const int resized_width=panel->width();
  panel->Collapse();EXPECT_FALSE(panel->GetVisible());panel->Show();EXPECT_EQ(panel->width(),resized_width);
  panel->ConfigureForTesting("ollama","test-local",{true,true,true,false,false});
  // A running task keeps working while the unpinned panel hides.
  panel->SendForTesting("Read page");ASSERT_TRUE(panel->busy());
  panel->OnResize(1000, true);
  for (auto theme : {ThemeMode::kLight, ThemeMode::kDark}) {
    window_->shell()->SetThemeMode(theme);
    window_->widget()->LayoutRootViewIfNecessary();
    auto* model = FindButton(panel, TF(u"Model: {}. Zmień model", {u"test-local"}));
    auto* background = FindButton(panel, T(u"Dokończ w tle"));
    ASSERT_TRUE(model);
    ASSERT_TRUE(background);
    EXPECT_EQ(background->width(), 28);
    EXPECT_GE(model->width(), model->GetPreferredSize().width());
  }
  panel->Collapse();EXPECT_FALSE(panel->GetVisible());EXPECT_TRUE(panel->busy());
  panel->Show();panel->RevokeAccess();EXPECT_FALSE(panel->busy());
}

IN_PROC_BROWSER_TEST_F(ZitterProfilesBrowserTest, AssistantOpensOnlyFromItsButton) {
  ASSERT_FALSE(window_->assistant());
  window_->widget()->LayoutRootViewIfNecessary();
  auto* shell=window_->shell();
  // The right edge is the page's scrollbar, not a trigger: no strip sits there.
  EXPECT_FALSE(shell->assistant_edge_visible_for_testing());
  const auto bounds=shell->content_host()->parent()->GetBoundsInScreen();
  auto* root=shell->content_host()->parent();
  gfx::Point edge(bounds.width()-4,bounds.height()/2);
  auto* hit=root->GetEventHandlerForPoint(edge);
  EXPECT_FALSE(hit&&std::string_view(hit->GetClassName())=="EdgeView");
  auto* bar=window_->extensions_bar();ASSERT_TRUE(bar);
  window_->AssistantStateChanged();
  ASSERT_TRUE(base::test::RunUntil([&]{return bar->assistant_button_for_testing()!=nullptr;}));
  auto click=[&]{static_cast<views::Button*>(bar->assistant_button_for_testing())->button_controller()->NotifyClick();};
  click();
  ASSERT_TRUE(window_->assistant());auto* panel=window_->assistant();EXPECT_TRUE(panel->GetVisible());
  panel->TypeForTesting(u"Keep the draft");
  // The button closes and reopens it; Esc closes it.
  click();EXPECT_FALSE(panel->GetVisible());
  click();EXPECT_TRUE(panel->GetVisible());EXPECT_EQ(panel->draft_for_testing(),u"Keep the draft");
  EXPECT_TRUE(panel->HandleEscape());EXPECT_FALSE(panel->GetVisible());
  // A pinned panel also goes away from the button.
  click();panel->SetPinned(true);click();EXPECT_FALSE(panel->GetVisible());
}
IN_PROC_BROWSER_TEST_F(ZitterProfilesBrowserTest, AssistantToolbarStartsFreshConversationAndPreservesDraft) {
  window_->ShowAssistant();auto* panel=window_->assistant();
  ASSERT_TRUE(base::test::RunUntil([&]{return panel->sessions_loaded_for_testing();}));
  panel->SeedExchangeForTesting("Earlier conversation","Earlier answer");
  panel->TypeForTesting(u"Unsent message");const auto initial=panel->sessions_for_testing();
  auto* bar=window_->extensions_bar();
  bar->RunAssistantCommandForTesting(5);
  EXPECT_TRUE(panel->GetVisible());EXPECT_EQ(panel->sessions_for_testing(),initial+1);
  EXPECT_TRUE(panel->draft_for_testing().empty());EXPECT_TRUE(panel->chips_for_testing().empty());EXPECT_FALSE(panel->busy());
  // An existing blank conversation must not absorb an explicit New conversation.
  bar->RunAssistantCommandForTesting(5);EXPECT_EQ(panel->sessions_for_testing(),initial+2);
  panel->SelectSessionForTesting(initial-1);EXPECT_EQ(panel->draft_for_testing(),u"Unsent message");
}

IN_PROC_BROWSER_TEST_F(ZitterProfilesBrowserTest, AssistantAutoHideTracksPointerAndPreservesDraft) {
  base::test::ScopedRunLoopTimeout timeout(FROM_HERE,base::Seconds(8));
  EnableNativeUIControls();
  ASSERT_TRUE(ui_test_utils::ShowAndFocusNativeWindow(window_->widget()->GetNativeWindow()));
  window_->ShowAssistant();auto* panel=window_->assistant();panel->SetPinned(true);
  window_->widget()->LayoutRootViewIfNecessary();
  const auto native=window_->widget()->GetNativeWindow();
  auto move=[&](gfx::Point point){base::test::TestFuture<void> moved;return ui_controls::SendMouseMoveNotifyWhenDone(point.x(),point.y(),moved.GetCallback(),native)&&moved.Wait();};
  const auto inside=panel->GetBoundsInScreen().CenterPoint();
  const auto outside=gfx::Point(panel->GetBoundsInScreen().x()-60,inside.y());
  ASSERT_TRUE(move(inside));panel->SetPinned(false);
  // A focused draft and a menu used to prevent collapse permanently.
  panel->TypeForTesting(u"Keep this draft after pointer departure");
  panel->ToggleMenuForTesting(AssistantPanel::Menu::kModel);
  ASSERT_TRUE(move(outside));
  EXPECT_EQ(display::Screen::Get()->GetCursorScreenPoint(),outside);
  EXPECT_FALSE(panel->GetBoundsInScreen().Contains(outside)) << panel->GetBoundsInScreen().ToString();
  ASSERT_TRUE(base::test::RunUntil([&]{return !panel->GetVisible();}));
  EXPECT_EQ(panel->draft_for_testing(),u"Keep this draft after pointer departure");
  panel->Show();panel->ToggleMenuForTesting(AssistantPanel::Menu::kModel);
  ASSERT_TRUE(move(inside));
  // Finishing a resize outside must still hide, without another exit event.
  panel->OnResize(20,false);ASSERT_TRUE(move(outside));
  panel->Collapse();EXPECT_TRUE(panel->GetVisible());
  panel->OnResize(20,true);
  ASSERT_TRUE(base::test::RunUntil([&]{return !panel->GetVisible();}));
  panel->Show();EXPECT_EQ(panel->draft_for_testing(),u"Keep this draft after pointer departure");
  // Opening from the button or a command also watches the pointer once it moves.
  const auto farther=gfx::Point(outside.x()-20,outside.y());ASSERT_TRUE(move(farther));
  ASSERT_TRUE(base::test::RunUntil([&]{return !panel->GetVisible();}));
}

// Opt in: timing runs must not silently turn functional verification into a
// benchmark or use real browsing profiles. The Python runner preserves samples.
IN_PROC_BROWSER_TEST_F(ZitterProfilesBrowserTest, PerformanceBaseline) {
  const auto* command = base::CommandLine::ForCurrentProcess();
  if (!command->HasSwitch("zitter-benchmark")) GTEST_SKIP();
  int iterations = 30, tabs = 25;
  if (command->HasSwitch("zitter-perf-iterations"))
    ASSERT_TRUE(base::StringToInt(command->GetSwitchValueASCII("zitter-perf-iterations"), &iterations));
  if (command->HasSwitch("zitter-perf-tabs"))
    ASSERT_TRUE(base::StringToInt(command->GetSwitchValueASCII("zitter-perf-tabs"), &tabs));
  ASSERT_GE(iterations, 1); ASSERT_LE(iterations, 200);
  ASSERT_GE(tabs, 2); ASSERT_LE(tabs, 200);
  base::test::ScopedRunLoopTimeout timeout(FROM_HERE, base::Seconds(30));
  ASSERT_TRUE(window_->Select("work"));
  const auto url = embedded_test_server()->GetURL("/performance_probe.html");
  ASSERT_TRUE(content::NavigateToURL(window_->contents("work"), url));
  for (int i = 1; i < tabs; ++i) {
    ASSERT_TRUE(window_->NavigateFromBar(url, true));
    ASSERT_TRUE(content::WaitForLoadStop(window_->contents("work")));
  }

  class FirstPaint final : public content::WebContentsObserver {
   public:
    FirstPaint(content::WebContents* page, base::TimeTicks start)
        : content::WebContentsObserver(page), start_(start) {}
    void DidFirstVisuallyNonEmptyPaint() override {
      if (!elapsed) elapsed = base::TimeTicks::Now() - start_;
    }
    std::optional<base::TimeDelta> elapsed;
   private:
    const base::TimeTicks start_;
  };
  auto sample = [](const char* metric, int trial, double milliseconds) {
    LOG(INFO) << "ZITTER_PERF {\"metric\":\"" << metric << "\",\"trial\":"
              << trial << ",\"ms\":" << milliseconds << "}";
  };
  // Two warmups are explicitly excluded; these are warm-profile measurements,
  // not cold application startup or internet/DNS/TLS measurements.
  for (int trial = -2; trial < iterations; ++trial) {
    auto& spare_manager = content::SpareRenderProcessHostManager::Get();
    const auto spare_ids = spare_manager.GetSpareIds();
    size_t ready_matching_spares = 0;
    auto* context = window_->contents("work")->GetBrowserContext();
    for (const auto& spare : spare_manager.GetSpares())
      if (spare->GetBrowserContext() == context && spare->IsReady()) ++ready_matching_spares;
    const auto start = base::TimeTicks::Now();
    ASSERT_TRUE(window_->NavigateFromBar(url, true));
    const auto dispatched = base::TimeTicks::Now();
    FirstPaint paint(window_->contents("work"), start);
    ASSERT_TRUE(base::test::RunUntil([&] { return paint.elapsed.has_value(); }));
    ASSERT_TRUE(content::WaitForLoadStop(window_->contents("work")));
    if (trial >= 0) {
      sample("new_tab_dispatch_ms", trial, (dispatched - start).InMillisecondsF());
      sample("new_tab_first_visual_paint_ms", trial, paint.elapsed->InMillisecondsF());
      const auto process_id = window_->contents("work")->GetPrimaryMainFrame()->GetProcess()->GetID();
      LOG(INFO) << "ZITTER_RENDERER {\"trial\":" << trial << ",\"spares_before\":" << spare_ids.size()
                << ",\"ready_matching_spares_before\":" << ready_matching_spares
                << ",\"used_spare\":" << (std::find(spare_ids.begin(), spare_ids.end(), process_id) != spare_ids.end() ? "true" : "false") << "}";
    }
    window_->CloseTab(tabs);
  }
  window_->SelectTab(1);
  auto* right_page = window_->contents("work");
  ASSERT_EQ(true, content::EvalJs(right_page,
      "new Promise(resolve => requestAnimationFrame(() => requestAnimationFrame(() => resolve(true))))"));
  for (int trial = -2; trial < iterations; ++trial) {
    window_->SelectTab(0);
    ASSERT_EQ(true, content::EvalJs(window_->contents("work"),
        "new Promise(resolve => requestAnimationFrame(() => requestAnimationFrame(() => resolve(true))))"));
    // Arm both before changing bounds/visibility, so sequential waits cannot
    // accidentally miss a frame that arrived while waiting for the other pane.
    content::RenderFrameSubmissionObserver left(window_->contents("work"));
    content::RenderFrameSubmissionObserver right(right_page);
    left.SetWaitForNextFrame(); right.SetWaitForNextFrame();
    const auto start = base::TimeTicks::Now();
    ASSERT_TRUE(window_->SplitTab(1));
    const auto dispatched = base::TimeTicks::Now();
    left.WaitForNextFrameSubmission(); right.WaitForNextFrameSubmission();
    const auto frames_ready = base::TimeTicks::Now();
    if (trial >= 0) {
      sample("split_dispatch_ms", trial, (dispatched - start).InMillisecondsF());
      sample("split_both_renderer_frames_ms", trial, (frames_ready - start).InMillisecondsF());
    }
    window_->Unsplit(0);
    // Let the full-width state reach the renderer before the next resize.
    ASSERT_EQ(true, content::EvalJs(window_->contents("work"),
        "new Promise(resolve => requestAnimationFrame(() => requestAnimationFrame(() => resolve(true))))"));
  }
}

// Real-app UI interaction workload for Views vs Rust/Metal comparison: sidebar
// tab selection, folder collapse and palette query, each measured until the
// posted UI work (including Metal scene updates) has drained.
IN_PROC_BROWSER_TEST_F(ZitterProfilesBrowserTest, PerformanceUiInteraction) {
  const auto* command = base::CommandLine::ForCurrentProcess();
  if (!command->HasSwitch("zitter-benchmark")) GTEST_SKIP();
  int iterations = 40, tabs = 20;
  if (command->HasSwitch("zitter-perf-iterations"))
    ASSERT_TRUE(base::StringToInt(command->GetSwitchValueASCII("zitter-perf-iterations"), &iterations));
  if (command->HasSwitch("zitter-perf-tabs"))
    ASSERT_TRUE(base::StringToInt(command->GetSwitchValueASCII("zitter-perf-tabs"), &tabs));
  ASSERT_GE(iterations, 1); ASSERT_LE(iterations, 400);
  ASSERT_GE(tabs, 2); ASSERT_LE(tabs, 100);
  base::test::ScopedRunLoopTimeout timeout(FROM_HERE, base::Seconds(120));
  ASSERT_TRUE(window_->Select("work"));
  auto* shell = window_->shell();
  ASSERT_TRUE(base::test::RunUntil([&] { return shell->appearance_ready(); }));
  shell->SetWorkspaceAnimations(false);
  const auto url = embedded_test_server()->GetURL("/performance_probe.html");
  ASSERT_TRUE(content::NavigateToURL(window_->contents("work"), url));
  for (int i = 1; i < tabs; ++i) ASSERT_TRUE(window_->NavigateFromBar(url, true));
  ASSERT_TRUE(window_->CreatePinnedFolder("work", "", "Perf folder"));
  ASSERT_TRUE(base::test::RunUntil([&] { return !window_->profiles_busy(); }));
  shell->SetPinned(true); shell->ShowSidebar();
  auto drain = [&] { base::RunLoop().RunUntilIdle(); shell->sidebar_widget()->LayoutRootViewIfNecessary(); base::RunLoop().RunUntilIdle(); };
  drain();
  auto sample = [](const char* metric, int trial, double milliseconds) {
    LOG(INFO) << "ZITTER_PERF {\"metric\":\"" << metric << "\",\"trial\":" << trial << ",\"ms\":" << milliseconds << "}";
  };
  auto metrics = base::ProcessMetrics::CreateCurrentProcessMetrics();
  std::optional<base::TimeDelta> cpu_start;
  for (int trial = -3; trial < iterations; ++trial) {
    if (trial == 0) { const auto cpu = metrics->GetCumulativeCPUUsage(); ASSERT_TRUE(cpu.has_value()); cpu_start = *cpu; }
    const auto wall = base::TimeTicks::Now();
    auto* row = shell->tab_button(static_cast<size_t>((trial + 3) % tabs));
    ASSERT_TRUE(row);
    auto start = base::TimeTicks::Now();
    ActivateSidebarRow(row); drain();
    if (trial >= 0) sample("ui_tab_select_ms", trial, (base::TimeTicks::Now() - start).InMillisecondsF());
    auto* folder = FindButton(shell->sidebar_view(), (trial % 2) ? u"▸ Perf folder" : u"▾ Perf folder");
    if (!folder) folder = FindButton(shell->sidebar_view(), u"▸ Perf folder");
    if (!folder) folder = FindButton(shell->sidebar_view(), u"▾ Perf folder");
    ASSERT_TRUE(folder);
    start = base::TimeTicks::Now();
    ActivateSidebarRow(folder); drain();
    if (trial >= 0) sample("ui_folder_toggle_ms", trial, (base::TimeTicks::Now() - start).InMillisecondsF());
    start = base::TimeTicks::Now();
    shell->OpenCommandPalette();
    const auto shown = base::TimeTicks::Now();
    base::RunLoop().RunUntilIdle();
    const auto idle = base::TimeTicks::Now();
    drain();
    const auto opened = base::TimeTicks::Now();
    if (trial >= 0) {
      sample("ui_palette_open_call_ms", trial, (shown - start).InMillisecondsF());
      sample("ui_palette_open_idle_ms", trial, (idle - shown).InMillisecondsF());
    }
    SetPaletteQuery(u"przes"); drain();
    const auto queried = base::TimeTicks::Now();
    shell->CloseOverlays(true); drain();
    if (trial >= 0) {
      sample("ui_palette_query_ms", trial, (base::TimeTicks::Now() - start).InMillisecondsF());
      sample("ui_palette_open_part_ms", trial, (opened - start).InMillisecondsF());
      sample("ui_palette_type_part_ms", trial, (queried - opened).InMillisecondsF());
      sample("ui_palette_close_part_ms", trial, (base::TimeTicks::Now() - queried).InMillisecondsF());
    }
    if (trial >= 0) sample("ui_iteration_ms", trial, (base::TimeTicks::Now() - wall).InMillisecondsF());
  }
  const auto cpu_end = metrics->GetCumulativeCPUUsage();
  ASSERT_TRUE(cpu_end.has_value());
  auto memory = metrics->GetMemoryInfo();
  ASSERT_TRUE(memory.has_value());
  uint64_t footprint = 0;
#if BUILDFLAG(IS_APPLE)
  footprint = memory->physical_footprint_bytes;
#endif
  LOG(INFO) << "ZITTER_UI_RESOURCE {\"iterations\":" << iterations << ",\"tabs\":" << tabs
            << ",\"browser_cpu_ms\":" << (*cpu_end - *cpu_start).InMillisecondsF()
            << ",\"browser_resident_bytes\":" << memory->resident_set_bytes
            << ",\"browser_footprint_bytes\":" << footprint << "}";
#if BUILDFLAG(IS_MAC)
  const auto stats = GetSidebarMetalStatsForTesting();
  LOG(INFO) << "ZITTER_UI_METAL {\"surfaces\":" << stats.surfaces << ",\"visible\":" << stats.visible
            << ",\"text_bytes\":" << stats.text_bytes << ",\"drawable_bytes\":" << stats.drawable_bytes << ",\"device_bytes\":" << stats.device_bytes << ",\"frames\":" << stats.frames << ",\"drawable_wait_ms\":" << stats.drawable_wait_ms << ",\"render_ms\":" << stats.render_ms << "}";
#endif
}
// Matched product-boundary workload: unchanged APIs on both product versions.
// Dispatch includes synchronous UI projection; settled additionally includes
// asynchronous persistence and posted layout work, not monitor presentation.
IN_PROC_BROWSER_TEST_F(ZitterProfilesBrowserTest, PerformanceProductBoundary) {
  const auto* command = base::CommandLine::ForCurrentProcess();
  if (!command->HasSwitch("zitter-benchmark")) GTEST_SKIP();
  int iterations = 20, pins = 1000;
  if (command->HasSwitch("zitter-perf-iterations"))
    ASSERT_TRUE(base::StringToInt(command->GetSwitchValueASCII("zitter-perf-iterations"), &iterations));
  if (command->HasSwitch("zitter-perf-pins"))
    ASSERT_TRUE(base::StringToInt(command->GetSwitchValueASCII("zitter-perf-pins"), &pins));
  ASSERT_GE(iterations, 1); ASSERT_LE(iterations, 400);
  ASSERT_GE(pins, 40); ASSERT_LE(pins, 5000);
  base::test::ScopedRunLoopTimeout timeout(FROM_HERE, base::Seconds(120));
  auto* shell = window_->shell();
  ASSERT_TRUE(base::test::RunUntil([&] { return shell->appearance_ready() && shell->tools_ready(); }));
  shell->SetWorkspaceAnimations(false);
  for (int i = 0; i < 8; ++i)
    ASSERT_TRUE(window_->AddWorkspace("Benchmark " + std::to_string(i), "work-profile"));
  ASSERT_TRUE(window_->Select("work"));
  const auto url = embedded_test_server()->GetURL("/performance_probe.html");
  ASSERT_TRUE(content::NavigateToURL(window_->contents("work"), url));
  shell->SetPinned(true); shell->ShowSidebar();
  for (const auto& entry : window_->CommandResults(u">"))
    shell->RecordCommandUse(entry.command_id, entry.target_workspace_id);
  ASSERT_TRUE(base::test::RunUntil([&] { return shell->appearance_saved() && window_->configuration_saved(); }));
  auto drain = [&] {
    base::RunLoop().RunUntilIdle();
    shell->sidebar_widget()->LayoutRootViewIfNecessary();
    base::RunLoop().RunUntilIdle();
  };
  // Child-before-parent order exercises imported catalogues. A 32-level group
  // makes repeated descendant scans visible without violating UI depth bounds.
  std::vector<PinnedItem> catalogue;
  for (int i = 0; i < pins - 34; ++i)
    catalogue.push_back({"perf-leaf-" + std::to_string(i), "perf-chain-31", "Benchmark pin", url, false});
  for (int i = 31; i >= 0; --i)
    catalogue.push_back({"perf-chain-" + std::to_string(i), i ? "perf-chain-" + std::to_string(i - 1) : "perf-root-a",
                         "Benchmark folder", GURL(), true});
  catalogue.push_back({"perf-root-a", "", "Group A", GURL(), true});
  catalogue.push_back({"perf-root-b", "", "Group B", GURL(), true});
  ASSERT_EQ(static_cast<size_t>(pins), catalogue.size());
  drain();
  LOG(INFO) << "ZITTER_BOUNDARY_READY pins=" << pins;
  auto emit = [](const char* metric, int trial, double ms) {
    if (trial >= 0) LOG(INFO) << "ZITTER_PERF {\"metric\":\"" << metric << "\",\"trial\":" << trial << ",\"ms\":" << ms << "}";
  };
  auto metrics = base::ProcessMetrics::CreateCurrentProcessMetrics();
  std::optional<base::TimeDelta> cpu_start;
  for (int trial = -3; trial < iterations; ++trial) {
    if (trial == 0) {
      const auto cpu = metrics->GetCumulativeCPUUsage(); ASSERT_TRUE(cpu.has_value()); cpu_start = *cpu;
    }
    auto start = base::TimeTicks::Now();
    size_t command_count = 0;
    constexpr int kCommandBatch = 100;
    for (int i = 0; i < kCommandBatch; ++i) command_count += window_->CommandResults(u">").size();
    emit("command_catalogue_per_call_ms", trial, (base::TimeTicks::Now() - start).InMillisecondsF() / kCommandBatch);
    ASSERT_GT(command_count, 0u);

    start = base::TimeTicks::Now();
    ASSERT_TRUE(window_->RestorePins("work", catalogue));
    const auto restored = base::TimeTicks::Now();
    ASSERT_TRUE(base::test::RunUntil([&] { return !window_->profiles_busy(); })); drain();
    emit("pin_restore_dispatch_ms", trial, (restored - start).InMillisecondsF());
    emit("pin_restore_settled_ms", trial, (base::TimeTicks::Now() - start).InMillisecondsF());
    ASSERT_EQ(static_cast<size_t>(pins), window_->pinned_items("work").size());

    start = base::TimeTicks::Now();
    ASSERT_TRUE(window_->MovePin("perf-root-a", "perf-root-b", {}));
    const auto moved = base::TimeTicks::Now();
    ASSERT_TRUE(base::test::RunUntil([&] { return !window_->profiles_busy(); })); drain();
    emit("pin_move_dispatch_ms", trial, (moved - start).InMillisecondsF());
    emit("pin_move_settled_ms", trial, (base::TimeTicks::Now() - start).InMillisecondsF());

    start = base::TimeTicks::Now();
    ASSERT_TRUE(window_->RemovePinnedFolder("work", "perf-root-a", true));
    const auto removed = base::TimeTicks::Now();
    ASSERT_TRUE(base::test::RunUntil([&] { return !window_->profiles_busy(); })); drain();
    emit("pin_delete_dispatch_ms", trial, (removed - start).InMillisecondsF());
    emit("pin_delete_settled_ms", trial, (base::TimeTicks::Now() - start).InMillisecondsF());
    ASSERT_EQ(1u, window_->pinned_items("work").size());
  }
  const auto cpu_end = metrics->GetCumulativeCPUUsage(); ASSERT_TRUE(cpu_end.has_value());
  const auto memory = metrics->GetMemoryInfo(); ASSERT_TRUE(memory.has_value());
  uint64_t footprint = 0;
#if BUILDFLAG(IS_APPLE)
  footprint = memory->physical_footprint_bytes;
#endif
  LOG(INFO) << "ZITTER_UI_RESOURCE {\"iterations\":" << iterations << ",\"pins\":" << pins
            << ",\"browser_cpu_ms\":" << (*cpu_end - *cpu_start).InMillisecondsF()
            << ",\"browser_footprint_bytes\":" << footprint << "}";
}

// A wide catalogue keeps unrelated branches present during local edits.
IN_PROC_BROWSER_TEST_F(ZitterProfilesBrowserTest, PerformanceSidebarSubtree) {
  const auto* command = base::CommandLine::ForCurrentProcess();
  if (!command->HasSwitch("zitter-benchmark")) GTEST_SKIP();
  int iterations = 20, pins = 1000;
  if (command->HasSwitch("zitter-perf-iterations"))
    ASSERT_TRUE(base::StringToInt(command->GetSwitchValueASCII("zitter-perf-iterations"), &iterations));
  if (command->HasSwitch("zitter-perf-pins"))
    ASSERT_TRUE(base::StringToInt(command->GetSwitchValueASCII("zitter-perf-pins"), &pins));
  ASSERT_GE(iterations, 1); ASSERT_LE(iterations, 400);
  ASSERT_GE(pins, 100); ASSERT_LE(pins, 5000);
  base::test::ScopedRunLoopTimeout timeout(FROM_HERE, base::Seconds(120));
  auto* shell = window_->shell();
  ASSERT_TRUE(base::test::RunUntil([&] { return shell->appearance_ready() && shell->tools_ready(); }));
  shell->SetWorkspaceAnimations(false);
  shell->SetPinned(true); shell->ShowSidebar();
  const auto url = embedded_test_server()->GetURL("/performance_probe.html");
  ASSERT_TRUE(content::NavigateToURL(window_->contents("work"), url));
  std::vector<PinnedItem> catalogue;
  constexpr int kFolders = 24;
  for (int i = 0; i < kFolders; ++i)
    catalogue.push_back({"branch-" + std::to_string(i), "", "Folder", GURL(), true});
  for (int i = 0; i < pins - kFolders; ++i)
    catalogue.push_back({"leaf-" + std::to_string(i), "branch-" + std::to_string(i % kFolders), "Pin", url, false});
  auto drain = [&] {
    ASSERT_TRUE(base::test::RunUntil([&] { return !window_->profiles_busy(); }));
    base::RunLoop().RunUntilIdle();
    shell->sidebar_widget()->LayoutRootViewIfNecessary();
    base::RunLoop().RunUntilIdle();
  };
  ASSERT_TRUE(window_->RestorePins("work", catalogue)); drain();
  auto emit = [](std::string metric, int trial, base::TimeTicks start) {
    if (trial >= 0) LOG(INFO) << "ZITTER_PERF {\"metric\":\"" << metric << "\",\"trial\":" << trial
        << ",\"ms\":" << (base::TimeTicks::Now() - start).InMillisecondsF() << "}";
  };
  auto metrics = base::ProcessMetrics::CreateCurrentProcessMetrics();
  std::optional<base::TimeDelta> cpu_start;
  for (int trial = -3; trial < iterations; ++trial) {
    if (trial == 0) { const auto cpu = metrics->GetCumulativeCPUUsage(); ASSERT_TRUE(cpu.has_value()); cpu_start = *cpu; }
    auto start = base::TimeTicks::Now();
    ASSERT_TRUE(window_->MovePin("leaf-0", "branch-1", {}));
    emit("leaf_move_dispatch_ms", trial, start); drain(); emit("leaf_move_settled_ms", trial, start);
    start = base::TimeTicks::Now();
    ASSERT_TRUE(window_->MovePin("branch-2", "branch-3", {}));
    emit("branch_move_dispatch_ms", trial, start); drain(); emit("branch_move_settled_ms", trial, start);
    start = base::TimeTicks::Now();
    ASSERT_TRUE(window_->RemovePinnedFolder("work", "branch-4", true));
    emit("branch_delete_dispatch_ms", trial, start); drain(); emit("branch_delete_settled_ms", trial, start);
    ASSERT_LT(window_->pinned_items("work").size(), catalogue.size());
    start = base::TimeTicks::Now();
    ASSERT_TRUE(window_->RestorePins("work", catalogue));
    emit("catalogue_restore_dispatch_ms", trial, start); drain(); emit("catalogue_restore_settled_ms", trial, start);
    ASSERT_EQ(catalogue, window_->pinned_items("work"));
  }
  const auto cpu_end = metrics->GetCumulativeCPUUsage(); ASSERT_TRUE(cpu_end.has_value());
  const auto memory = metrics->GetMemoryInfo(); ASSERT_TRUE(memory.has_value());
  uint64_t footprint = 0;
#if BUILDFLAG(IS_APPLE)
  footprint = memory->physical_footprint_bytes;
#endif
  LOG(INFO) << "ZITTER_UI_RESOURCE {\"iterations\":" << iterations << ",\"pins\":" << pins
      << ",\"browser_cpu_ms\":" << (*cpu_end - *cpu_start).InMillisecondsF()
      << ",\"browser_footprint_bytes\":" << footprint << "}";
}

IN_PROC_BROWSER_TEST_F(ZitterProfilesBrowserTest, PerformanceRestoration) {
  const auto* command = base::CommandLine::ForCurrentProcess();
  if (!command->HasSwitch("zitter-benchmark")) GTEST_SKIP();
  int iterations = 30, tabs = 25;
  if (command->HasSwitch("zitter-perf-iterations"))
    ASSERT_TRUE(base::StringToInt(command->GetSwitchValueASCII("zitter-perf-iterations"), &iterations));
  if (command->HasSwitch("zitter-perf-tabs"))
    ASSERT_TRUE(base::StringToInt(command->GetSwitchValueASCII("zitter-perf-tabs"), &tabs));
  ASSERT_GE(iterations, 1); ASSERT_LE(iterations, 200);
  ASSERT_GE(tabs, 2); ASSERT_LE(tabs, 200);
  base::test::ScopedRunLoopTimeout timeout(FROM_HERE, base::Seconds(30));
  ASSERT_TRUE(window_->Select("work"));
  ASSERT_TRUE(base::test::RunUntil([&] { return window_->configuration_saved(); }));
  base::DictValue session;
  for (const std::string id : {"work", "personal"}) {
    base::DictValue host;
    host.Set("profile_id", id + "-profile"); host.Set("active", 0);
    host.Set("left", 0); host.Set("right", id == "work" ? 1 : -1); host.Set("ratio", 0.5);
    base::ListValue pages;
    for (int i = 0; i < tabs; ++i) {
      base::DictValue page;
      page.Set("url", embedded_test_server()->GetURL(
          "/performance_probe.html?restore=" + id + std::to_string(i)).spec());
      page.Set("title", "Saved " + id + std::to_string(i)); pages.Append(std::move(page));
    }
    host.Set("tabs", std::move(pages)); session.Set(id, std::move(host));
  }
  std::string json;
  ASSERT_TRUE(base::JSONWriter::Write(session, &json));
  const auto directory = g_browser_process->profile_manager()->user_data_dir();
  for (int trial = -2; trial < iterations; ++trial) {
    window_.reset();
    base::ThreadPoolInstance::Get()->FlushForTesting();
    {
      base::ScopedAllowBlockingForTesting allow;
      ASSERT_TRUE(base::WriteFile(directory.AppendASCII("ZitterSession.json"), json));
      ASSERT_TRUE(base::WriteFile(directory.AppendASCII("ZitterTimeline.jsonl"), ""));
    }
    const auto start = base::TimeTicks::Now();
    SetUiLanguageForTesting("pl");  // Assertions read the Polish UI.
    window_ = std::make_unique<WorkspaceWindow>(work_, personal_);
    ASSERT_TRUE(base::test::RunUntil([&] { return window_->configuration_ready(); }));
    const auto ready = base::TimeTicks::Now();
    ASSERT_TRUE(window_->split());
    auto* left = window_->pane_contents(false);
    auto* right = window_->pane_contents(true);
    ASSERT_TRUE(left); ASSERT_TRUE(right);
    ASSERT_TRUE(base::test::RunUntil([&] {
      return left->CompletedFirstVisuallyNonEmptyPaint() && right->CompletedFirstVisuallyNonEmptyPaint();
    }));
    const auto painted = base::TimeTicks::Now();
    size_t live = 0;
    for (const auto& child : window_->shell()->content_host()->children()) {
      auto* view = views::AsViewClass<views::WebView>(child.get());
      if (view && view->web_contents()) ++live;
    }
    if (trial >= 0) {
      LOG(INFO) << "ZITTER_PERF {\"metric\":\"restore_ready_ms\",\"trial\":" << trial
                << ",\"ms\":" << (ready - start).InMillisecondsF() << "}";
      LOG(INFO) << "ZITTER_PERF {\"metric\":\"restore_both_first_paints_ms\",\"trial\":" << trial
                << ",\"ms\":" << (painted - start).InMillisecondsF() << "}";
    }
    ASSERT_TRUE(content::WaitForLoadStop(left));
    ASSERT_TRUE(content::WaitForLoadStop(right));
    ASSERT_TRUE(base::test::RunUntil([&] { return window_->configuration_saved(); }));
    if (trial >= 0) {
      auto memory = base::ProcessMetrics::CreateCurrentProcessMetrics()->GetMemoryInfo();
      ASSERT_TRUE(memory.has_value());
      uint64_t footprint = 0;
#if BUILDFLAG(IS_APPLE)
      footprint = memory->physical_footprint_bytes;
#endif
      LOG(INFO) << "ZITTER_RESOURCE {\"trial\":" << trial << ",\"realized_pages\":" << live
                << ",\"saved_tabs\":" << tabs * 2
                << ",\"browser_resident_bytes\":" << memory->resident_set_bytes
                << ",\"browser_physical_footprint_bytes\":" << footprint << "}";
    }
  }
}

IN_PROC_BROWSER_TEST_F(ZitterProfilesBrowserTest, PerformanceProfileStartup) {
  const auto* command = base::CommandLine::ForCurrentProcess();
  if (!command->HasSwitch("zitter-benchmark")) GTEST_SKIP();
  const bool with_page = command->HasSwitch("zitter-perf-profile-page");
  int iterations = 30, count = 4;
  if (command->HasSwitch("zitter-perf-iterations"))
    ASSERT_TRUE(base::StringToInt(command->GetSwitchValueASCII("zitter-perf-iterations"), &iterations));
  if (command->HasSwitch("zitter-perf-profiles"))
    ASSERT_TRUE(base::StringToInt(command->GetSwitchValueASCII("zitter-perf-profiles"), &count));
  ASSERT_GE(iterations, 1); ASSERT_LE(iterations, 200);
  ASSERT_GE(count, 2); ASSERT_LE(count, 16);
  base::test::ScopedRunLoopTimeout timeout(FROM_HERE, base::Seconds(30));
  ASSERT_TRUE(base::test::RunUntil([&] { return window_->configuration_saved(); }));
  auto* manager = g_browser_process->profile_manager();
  class Timings final : public ProfileManagerObserver {
   public:
    explicit Timings(const std::vector<base::FilePath>& paths) : paths_(paths) {}
    void OnProfileCreationStarted(Profile* profile) override {
      if (std::find(paths_.begin(), paths_.end(), profile->GetPath()) == paths_.end()) return;
      const auto now = base::TimeTicks::Now();
      if (first_start.is_null()) first_start = now;
      if (profile->GetPath() == paths_.back()) active_start = now;
    }
    void OnProfileAdded(Profile* profile) override {
      if (std::find(paths_.begin(), paths_.end(), profile->GetPath()) == paths_.end()) return;
      ++added; last_added = base::TimeTicks::Now();
    }
    base::TimeTicks first_start, active_start, last_added;
    size_t added = 0;
   private:
    const std::vector<base::FilePath> paths_;
  };
  for (int trial = -2; trial < iterations; ++trial) {
    window_.reset();
    base::ThreadPoolInstance::Get()->FlushForTesting();
    base::ListValue profiles, spaces;
    std::vector<base::FilePath> paths;
    for (int i = 0; i < count; ++i) {
      const auto directory = "ZitterProfile-" + base::Uuid::GenerateRandomV4().AsLowercaseString();
      const auto id = "cold-profile-" + std::to_string(i);
      paths.push_back(manager->user_data_dir().AppendASCII(directory));
      base::DictValue profile;
      profile.Set("id", id); profile.Set("name", "Cold " + std::to_string(i));
      profile.Set("directory", directory); profiles.Append(std::move(profile));
      base::DictValue space;
      space.Set("id", "cold-space-" + std::to_string(i)); space.Set("profile_id", id);
      space.Set("name", "Space " + std::to_string(i)); spaces.Append(std::move(space));
    }
    base::DictValue catalogue;
    catalogue.Set("profiles", std::move(profiles)); catalogue.Set("workspaces", std::move(spaces));
    catalogue.Set("active", "cold-space-" + std::to_string(count - 1));
    catalogue.Set("onboarding_complete", true);
    std::string json, session_json = "{}";
    ASSERT_TRUE(base::JSONWriter::Write(catalogue, &json));
    if (with_page) {
      base::DictValue session, host, tab;
      host.Set("profile_id", "cold-profile-" + std::to_string(count - 1));
      host.Set("active", 0); host.Set("left", 0); host.Set("right", -1);
      tab.Set("url", embedded_test_server()->GetURL("/performance_probe.html").spec());
      tab.Set("title", "Restored cold-profile page");
      base::ListValue tabs; tabs.Append(std::move(tab)); host.Set("tabs", std::move(tabs));
      session.Set("cold-space-" + std::to_string(count - 1), std::move(host));
      ASSERT_TRUE(base::JSONWriter::Write(session, &session_json));
    }
    {
      base::ScopedAllowBlockingForTesting allow;
      ASSERT_TRUE(base::WriteFile(manager->user_data_dir().AppendASCII("ZitterWorkspaces.json"), json));
      ASSERT_TRUE(base::WriteFile(manager->user_data_dir().AppendASCII("ZitterSession.json"), session_json));
      ASSERT_TRUE(base::WriteFile(manager->user_data_dir().AppendASCII("ZitterTimeline.jsonl"), ""));
    }
    Timings timings(paths);
    base::ScopedObservation<ProfileManager, ProfileManagerObserver> observation(&timings);
    observation.Observe(manager);
    const auto start = base::TimeTicks::Now();
    SetUiLanguageForTesting("pl");  // Assertions read the Polish UI.
    window_ = std::make_unique<WorkspaceWindow>(work_, personal_);
    ASSERT_TRUE(base::test::RunUntil([&] { return window_->configuration_ready(); }));
    const auto ready = base::TimeTicks::Now();
    base::TimeTicks painted;
    if (with_page) {
      auto* page = window_->contents(window_->active_id());
      ASSERT_TRUE(page);
      ASSERT_TRUE(base::test::RunUntil([&] { return page->CompletedFirstVisuallyNonEmptyPaint(); }));
      painted = base::TimeTicks::Now();
      ASSERT_TRUE(content::WaitForLoadStop(page));
    }
    ASSERT_TRUE(base::test::RunUntil([&] { return timings.added == static_cast<size_t>(count) && !window_->profiles_busy(); }));
    ASSERT_FALSE(timings.first_start.is_null()); ASSERT_FALSE(timings.active_start.is_null());
    if (trial >= 0) {
      if (with_page)
        LOG(INFO) << "ZITTER_PERF {\"metric\":\"profiles_first_visual_paint_ms\",\"trial\":" << trial
                  << ",\"ms\":" << (painted - start).InMillisecondsF() << "}";
      LOG(INFO) << "ZITTER_PERF {\"metric\":\"profiles_ready_ms\",\"trial\":" << trial
                << ",\"ms\":" << (ready - start).InMillisecondsF() << "}";
      LOG(INFO) << "ZITTER_PERF {\"metric\":\"profile_batch_ms\",\"trial\":" << trial
                << ",\"ms\":" << (timings.last_added - timings.first_start).InMillisecondsF() << "}";
      LOG(INFO) << "ZITTER_PERF {\"metric\":\"active_profile_delay_ms\",\"trial\":" << trial
                << ",\"ms\":" << (timings.active_start - timings.first_start).InMillisecondsF() << "}";
    }
    ASSERT_TRUE(base::test::RunUntil([&] { return window_->configuration_saved(); }));
    if (trial >= 0) {
      auto memory = base::ProcessMetrics::CreateCurrentProcessMetrics()->GetMemoryInfo();
      ASSERT_TRUE(memory.has_value());
      uint64_t footprint = 0;
#if BUILDFLAG(IS_APPLE)
      footprint = memory->physical_footprint_bytes;
#endif
      size_t live = 0;
      for (const auto& child : window_->shell()->content_host()->children()) {
        auto* view = views::AsViewClass<views::WebView>(child.get());
        if (view && view->web_contents()) ++live;
      }
      LOG(INFO) << "ZITTER_RESOURCE {\"trial\":" << trial << ",\"realized_pages\":" << live
                << ",\"saved_tabs\":" << count
                << ",\"browser_resident_bytes\":" << memory->resident_set_bytes
                << ",\"browser_physical_footprint_bytes\":" << footprint << "}";
    }
  }
}

IN_PROC_BROWSER_TEST_F(ZitterProfilesBrowserTest, SidebarMetadataUpdatesPreserveRows) {
  ASSERT_TRUE(window_->Select("work"));
  const auto url = embedded_test_server()->GetURL("/performance_probe.html");
  ASSERT_TRUE(content::NavigateToURL(window_->contents("work"), url));
  ASSERT_TRUE(window_->NavigateFromBar(url, true));
  auto* right = window_->contents("work");
  ASSERT_TRUE(content::WaitForLoadStop(right));
  window_->SelectTab(0);
  auto* shell = window_->shell();
  views::ViewTracker first(shell->tab_button(0)), second(shell->tab_button(1));
  ASSERT_TRUE(first); ASSERT_TRUE(second);
  ASSERT_TRUE(content::ExecJs(right, "document.title='Background title'; history.pushState({}, '', '/updated-path');"));
  ASSERT_TRUE(base::test::RunUntil([&] {
    return second && second.view()->GetTooltipText() == u"Background title";
  }));
  ASSERT_TRUE(first); ASSERT_TRUE(second);
  EXPECT_EQ(first.view(), shell->tab_button(0));
  EXPECT_EQ(second.view(), shell->tab_button(1));
  ASSERT_TRUE(window_->SplitTab(1));
  views::ViewTracker split_left(shell->tab_button(0)), split_right(shell->tab_button(1));
  ASSERT_TRUE(content::ExecJs(right, "document.title='Split title';"));
  ASSERT_TRUE(base::test::RunUntil([&] {
    return split_right && split_right.view()->GetTooltipText() == u"Split title";
  }));
  ASSERT_TRUE(split_left); ASSERT_TRUE(split_right);
  EXPECT_EQ(split_left.view(), shell->tab_button(0));
  EXPECT_EQ(split_right.view(), shell->tab_button(1));
  shell->SetPinned(true);shell->ShowSidebar();shell->sidebar_widget()->LayoutRootViewIfNecessary();
  // The retained callbacks must still select the original pages.
  ActivateSidebarRow(shell->tab_button(0));
  EXPECT_NE(right, window_->contents("work"));
  ActivateSidebarRow(shell->tab_button(1));
  EXPECT_EQ(right, window_->contents("work"));
}

IN_PROC_BROWSER_TEST_F(ZitterProfilesBrowserTest, TimeMachineFlushesPendingHistoryOnClose) {
  ASSERT_TRUE(window_->Select("work"));
  ASSERT_TRUE(content::NavigateToURL(window_->contents("work"), embedded_test_server()->GetURL("/storage_probe.html?pending")));
  ASSERT_TRUE(window_->SaveSnapshot("Pending close snapshot"));
  EXPECT_FALSE(window_->configuration_saved());  // The timeline line is still being appended.
  window_.reset();
  // Wait for the old window's BLOCK_SHUTDOWN writer, including the payload
  // explicitly flushed from its pending timer, before reopening the profile.
  base::ThreadPoolInstance::Get()->FlushForTesting();
  SetUiLanguageForTesting("pl");  // Assertions read the Polish UI.
  window_ = std::make_unique<WorkspaceWindow>(work_, personal_);
  ASSERT_TRUE(base::test::RunUntil([&] { return window_->configuration_ready(); }));
  const auto marks = window_->timeline_marks_for_testing();
  EXPECT_TRUE(std::ranges::contains(marks, "Pending close snapshot"));
  EXPECT_TRUE(window_->timeline_recorded_for_testing("work"));
}

IN_PROC_BROWSER_TEST_F(ZitterProfilesBrowserTest, RestoredTabsStayUnrealizedUntilShown) {
  ASSERT_TRUE(window_->Select("work"));
  ASSERT_TRUE(base::test::RunUntil([&] { return window_->configuration_saved(); }));
  window_.reset();
  base::ThreadPoolInstance::Get()->FlushForTesting();
  auto make_host = [&](std::string profile, std::string label, int count, bool split) {
    base::DictValue host;
    host.Set("profile_id", profile); host.Set("active", 0); host.Set("left", 0);
    host.Set("right", split ? 1 : -1); host.Set("ratio", 0.55);
    base::ListValue tabs;
    for (int i = 0; i < count; ++i) {
      base::DictValue tab;
      tab.Set("url", embedded_test_server()->GetURL(
          "/performance_probe.html?lazy=" + label + std::to_string(i)).spec());
      tab.Set("title", "Saved " + label + std::to_string(i));
      tabs.Append(std::move(tab));
    }
    host.Set("tabs", std::move(tabs));
    return host;
  };
  base::DictValue session;
  session.Set("work", make_host("work-profile", "work", 6, true));
  session.Set("personal", make_host("personal-profile", "personal", 2, false));
  std::string json;
  ASSERT_TRUE(base::JSONWriter::Write(session, &json));
  {
    base::ScopedAllowBlockingForTesting allow;
    ASSERT_TRUE(base::WriteFile(g_browser_process->profile_manager()->user_data_dir()
        .AppendASCII("ZitterSession.json"), json));
  }
  SetUiLanguageForTesting("pl");  // Assertions read the Polish UI.
  window_ = std::make_unique<WorkspaceWindow>(work_, personal_);
  ASSERT_TRUE(base::test::RunUntil([&] { return window_->configuration_ready(); }));
  auto live_pages = [&] {
    size_t count = 0;
    for (const auto& child : window_->shell()->content_host()->children()) {
      auto* view = views::AsViewClass<views::WebView>(child.get());
      if (view && view->web_contents()) ++count;
    }
    return count;
  };
  ASSERT_TRUE(window_->split());
  EXPECT_EQ(6u, window_->tab_count("work"));
  EXPECT_EQ(2u, window_->tab_count("personal"));
  EXPECT_EQ(2u, live_pages());  // Only the selected split has WebContents/clients.
  EXPECT_EQ(nullptr, window_->contents("personal"));
  ASSERT_TRUE(window_->SaveSnapshot("Unopened tabs retained"));
  const int64_t saved = window_->Now().InMillisecondsSinceUnixEpoch();
  window_->SearchPalette(u"Saved");
  window_->CloseTab(5);  // Closing a dormant tab must not realize it.
  EXPECT_EQ(2u, live_pages());
  window_->SelectTab(3);
  ASSERT_TRUE(content::WaitForLoadStop(window_->contents("work")));
  EXPECT_EQ(3u, live_pages());
  EXPECT_EQ(work_, window_->contents("work")->GetBrowserContext());
  EXPECT_EQ(embedded_test_server()->GetURL("/performance_probe.html?lazy=work3"),
            window_->contents("work")->GetLastCommittedURL());
  EXPECT_NE(nullptr, PageServices::FromWebContents(window_->contents("work")));
  ASSERT_TRUE(window_->Select("personal"));
  ASSERT_TRUE(content::WaitForLoadStop(window_->contents("personal")));
  EXPECT_EQ(4u, live_pages());
  EXPECT_EQ(personal_, window_->contents("personal")->GetBrowserContext());
  ASSERT_TRUE(window_->Select("work"));
  // Cmd+Shift+T brings back the dormant tab closed above.
  ASSERT_TRUE(window_->ReopenClosedTab());
  ASSERT_TRUE(content::WaitForLoadStop(window_->contents("work")));
  EXPECT_EQ(5u, live_pages());
  EXPECT_EQ(embedded_test_server()->GetURL("/performance_probe.html?lazy=work5"),
            window_->contents("work")->GetLastCommittedURL());
  EXPECT_FALSE(window_->ReopenClosedTab());
  // Time Machine returns the six tabs as they were saved; only the selection loads.
  window_->CloseTab(5);
  ASSERT_TRUE(window_->RestoreTimeline(saved, 0));
  EXPECT_EQ(6u, window_->tab_count("work"));
  EXPECT_FALSE(window_->split());
  EXPECT_EQ(2u, live_pages());  // Personal page plus the restored selection.
  ASSERT_TRUE(base::test::RunUntil([&] { return window_->configuration_saved(); }));
  window_.reset();
  base::ThreadPoolInstance::Get()->FlushForTesting();
  SetUiLanguageForTesting("pl");  // Assertions read the Polish UI.
  window_ = std::make_unique<WorkspaceWindow>(work_, personal_);
  ASSERT_TRUE(base::test::RunUntil([&] { return window_->configuration_ready(); }));
  EXPECT_EQ(6u, window_->tab_count("work"));
  EXPECT_EQ(1u, live_pages());  // The restored selection is outside its saved pair.
  EXPECT_EQ(nullptr, window_->contents("personal"));
}

IN_PROC_BROWSER_TEST_F(ZitterProfilesBrowserTest, StartupPrioritizesActiveProfileWithoutReorderingCatalogue) {
  ASSERT_TRUE(base::test::RunUntil([&] { return window_->configuration_saved(); }));
  window_.reset();
  base::ThreadPoolInstance::Get()->FlushForTesting();
  auto* manager = g_browser_process->profile_manager();
  std::vector<base::FilePath> paths;
  base::ListValue profiles, spaces;
  for (int i = 0; i < 4; ++i) {
    const auto directory = "ZitterProfile-" + base::Uuid::GenerateRandomV4().AsLowercaseString();
    const auto id = "cold-profile-" + std::to_string(i);
    paths.push_back(manager->user_data_dir().AppendASCII(directory));
    base::DictValue profile;
    profile.Set("id", id); profile.Set("name", "Cold " + std::to_string(i));
    profile.Set("directory", directory); profiles.Append(std::move(profile));
    base::DictValue space;
    space.Set("id", "cold-space-" + std::to_string(i));
    space.Set("profile_id", id); space.Set("name", "Space " + std::to_string(i));
    spaces.Append(std::move(space));
  }
  base::DictValue catalogue;
  catalogue.Set("profiles", std::move(profiles)); catalogue.Set("workspaces", std::move(spaces));
  catalogue.Set("active", "cold-space-3"); catalogue.Set("onboarding_complete", true);
  std::string json;
  ASSERT_TRUE(base::JSONWriter::Write(catalogue, &json));
  {
    base::ScopedAllowBlockingForTesting allow;
    ASSERT_TRUE(base::WriteFile(manager->user_data_dir().AppendASCII("ZitterWorkspaces.json"), json));
  }
  class CreationOrder final : public ProfileManagerObserver {
   public:
    explicit CreationOrder(const std::vector<base::FilePath>& expected) : expected_(expected) {}
    void OnProfileCreationStarted(Profile* profile) override {
      if (std::find(expected_.begin(), expected_.end(), profile->GetPath()) != expected_.end())
        started.push_back(profile->GetPath());
    }
    std::vector<base::FilePath> started;
   private:
    const std::vector<base::FilePath> expected_;
  } order(paths);
  base::ScopedObservation<ProfileManager, ProfileManagerObserver> observation(&order);
  observation.Observe(manager);
  SetUiLanguageForTesting("pl");  // Assertions read the Polish UI.
  window_ = std::make_unique<WorkspaceWindow>(work_, personal_);
  EXPECT_FALSE(window_->configuration_ready());
  ASSERT_TRUE(base::test::RunUntil([&] { return window_->configuration_ready(); }));
  ASSERT_EQ(1u, order.started.size());
  EXPECT_TRUE(window_->profiles_busy());
  EXPECT_EQ(paths[3], order.started.front());
  EXPECT_EQ("cold-space-3", window_->active_id());
  EXPECT_EQ(paths[3], window_->contents(window_->active_id())->GetBrowserContext()->GetPath());
  // Management cannot invalidate pending profile assignments. Ordinary active
  // browsing and queued cross-profile intents remain available.
  EXPECT_FALSE(window_->RenameProfile("cold-profile-0", "Changed during startup"));
  EXPECT_FALSE(window_->AssignProfile("cold-space-0", "cold-profile-3"));
  EXPECT_FALSE(window_->RemoveWorkspace());
  const auto cancelled = embedded_test_server()->GetURL("/performance_probe.html?cancelled");
  const auto superseded = embedded_test_server()->GetURL("/performance_probe.html?superseded");
  const auto final_url = embedded_test_server()->GetURL("/performance_probe.html?final");
  EXPECT_FALSE(window_->Select("cold-space-0"));
  EXPECT_EQ("cold-space-3", window_->active_id());
  EXPECT_TRUE(window_->OpenLink(cancelled, "cold-space-0", true));
  EXPECT_TRUE(window_->Select("cold-space-3"));  // cancels pending navigation
  EXPECT_TRUE(window_->OpenLink(superseded, "cold-space-1", true));
  EXPECT_TRUE(window_->OpenLink(final_url, "cold-space-2", true));
  EXPECT_EQ("cold-space-3", window_->active_id());
  EXPECT_FALSE(window_->contents("cold-space-0"));
  ASSERT_TRUE(base::test::RunUntil([&] {
    return window_->active_id() == "cold-space-2" &&
        window_->contents("cold-space-2")->GetLastCommittedURL() == final_url;
  }));
  EXPECT_EQ(paths[2], window_->contents("cold-space-2")->GetBrowserContext()->GetPath());
  EXPECT_TRUE(PageServices::FromWebContents(window_->contents("cold-space-2")));
  ASSERT_TRUE(base::test::RunUntil([&] { return !window_->profiles_busy(); }));
  EXPECT_FALSE(window_->contents("cold-space-0"));
  EXPECT_FALSE(window_->contents("cold-space-1"));
  EXPECT_TRUE(window_->contents("cold-space-3")->GetLastCommittedURL().is_empty());
  ASSERT_EQ(4u, order.started.size());
  const auto restored_profiles = window_->profiles();
  ASSERT_EQ(4u, restored_profiles.size());
  for (size_t i = 0; i < restored_profiles.size(); ++i) {
    EXPECT_EQ("cold-profile-" + std::to_string(i), restored_profiles[i].id);
    ASSERT_TRUE(window_->Select("cold-space-" + std::to_string(i)));
    EXPECT_EQ(paths[i], window_->contents(window_->active_id())->GetBrowserContext()->GetPath());
  }
  // Closing with a pending profile/navigation must invalidate both callbacks.
  ASSERT_TRUE(base::test::RunUntil([&] { return window_->configuration_saved(); }));
  window_.reset();
  base::ThreadPoolInstance::Get()->FlushForTesting();
  auto closing_catalogue = base::JSONReader::ReadDict(json, base::JSON_PARSE_RFC);
  ASSERT_TRUE(closing_catalogue);
  const auto closing_directory = "ZitterProfile-" + base::Uuid::GenerateRandomV4().AsLowercaseString();
  closing_catalogue->FindList("profiles")->front().GetDict().Set("directory", closing_directory);
  ASSERT_TRUE(base::JSONWriter::Write(*closing_catalogue, &json));
  {
    base::ScopedAllowBlockingForTesting allow;
    ASSERT_TRUE(base::WriteFile(manager->user_data_dir().AppendASCII("ZitterWorkspaces.json"), json));
  }
  SetUiLanguageForTesting("pl");  // Assertions read the Polish UI.
  window_ = std::make_unique<WorkspaceWindow>(work_, personal_);
  ASSERT_TRUE(base::test::RunUntil([&] { return window_->configuration_ready(); }));
  EXPECT_TRUE(window_->OpenLink(cancelled, "cold-space-0", true));
  base::test::TestFuture<Profile*> completed;
  manager->CreateProfileAsync(manager->user_data_dir().AppendASCII(closing_directory), completed.GetCallback());
  window_.reset();
  ASSERT_TRUE(completed.Wait());
  ASSERT_NE(nullptr, completed.Get());
  base::ThreadPoolInstance::Get()->FlushForTesting();
  SetUiLanguageForTesting("pl");  // Assertions read the Polish UI.
  window_ = std::make_unique<WorkspaceWindow>(work_, personal_);
  ASSERT_TRUE(base::test::RunUntil([&] { return window_->configuration_ready(); }));
  EXPECT_EQ("cold-space-3", window_->active_id());
  EXPECT_EQ(nullptr, window_->contents("cold-space-0"));
}

IN_PROC_BROWSER_TEST_F(ZitterProfilesBrowserTest, StartupProfileFailureKeepsActiveProfileUsable) {
  ASSERT_TRUE(base::test::RunUntil([&] { return window_->configuration_saved(); }));
  window_.reset();
  base::ThreadPoolInstance::Get()->FlushForTesting();
  auto* manager = g_browser_process->profile_manager();
  const auto directory = "ZitterProfile-" + base::Uuid::GenerateRandomV4().AsLowercaseString();
  base::ListValue profiles, spaces;
  for (int i = 0; i < 2; ++i) {
    base::DictValue profile;
    profile.Set("id", i == 0 ? "work-profile" : "broken-profile");
    profile.Set("name", i == 0 ? "Work" : "Broken");
    profile.Set("directory", i == 0 ? "ZitterWork" : directory);
    profiles.Append(std::move(profile));
    base::DictValue space;
    space.Set("id", i == 0 ? "work" : "broken");
    space.Set("profile_id", i == 0 ? "work-profile" : "broken-profile");
    space.Set("name", i == 0 ? "Work" : "Broken");
    spaces.Append(std::move(space));
  }
  base::DictValue catalogue;
  catalogue.Set("profiles", std::move(profiles)); catalogue.Set("workspaces", std::move(spaces));
  catalogue.Set("active", "work"); catalogue.Set("onboarding_complete", true);
  std::string json;
  ASSERT_TRUE(base::JSONWriter::Write(catalogue, &json));
  {
    base::ScopedAllowBlockingForTesting allow;
    ASSERT_TRUE(base::WriteFile(manager->user_data_dir().AppendASCII(directory), "not a directory"));
    ASSERT_TRUE(base::WriteFile(manager->user_data_dir().AppendASCII("ZitterWorkspaces.json"), json));
    ASSERT_TRUE(base::WriteFile(manager->user_data_dir().AppendASCII("ZitterSession.json"), "{}"));
  }
  SetUiLanguageForTesting("pl");  // Assertions read the Polish UI.
  window_ = std::make_unique<WorkspaceWindow>(work_, personal_);
  ASSERT_TRUE(base::test::RunUntil([&] { return window_->configuration_ready(); }));
  const auto url = embedded_test_server()->GetURL("/performance_probe.html?failed-profile");
  EXPECT_TRUE(window_->OpenLink(url, "broken", true));
  ASSERT_TRUE(base::test::RunUntil([&] { return window_->shell()->profiles_widget()->IsVisible(); }));
  EXPECT_EQ("work", window_->active_id());
  EXPECT_EQ(nullptr, window_->contents("broken"));
  EXPECT_EQ(work_, window_->contents("work")->GetBrowserContext());
  EXPECT_TRUE(window_->contents("work")->GetLastCommittedURL().is_empty());
  EXPECT_TRUE(window_->NavigateFromBar(embedded_test_server()->GetURL("/performance_probe.html"), true));
  ASSERT_TRUE(content::WaitForLoadStop(window_->contents("work")));
  EXPECT_EQ(work_, window_->contents("work")->GetBrowserContext());
}

IN_PROC_BROWSER_TEST_F(ZitterProfilesBrowserTest, KeywordSearchProvidersAndPersistence) {
  auto* shell = window_->shell();
  ASSERT_TRUE(base::test::RunUntil([&] { return shell->tools_ready(); }));
  EXPECT_EQ("https://www.google.com/search?q=hello+world", shell->ResolveInput("g hello world").spec());
  EXPECT_EQ("pl.wikipedia.org", shell->ResolveInput("w Warszawa").host());
  EXPECT_EQ("www.youtube.com", shell->ResolveInput("yt ambient").host());
  EXPECT_EQ("https://example.com/path", shell->ResolveInput("https://example.com/path").spec());
  EXPECT_EQ("http://example.com:8080/path", shell->ResolveInput("example.com:8080/path").spec());
  EXPECT_EQ("http://127.0.0.1:8080/path", shell->ResolveInput("127.0.0.1:8080/path").spec());
  EXPECT_FALSE(shell->ResolveInput("javascript:alert(1)").is_valid());
  EXPECT_FALSE(shell->ResolveInput("custom.scheme://example.com/path").is_valid());
  EXPECT_EQ("https://example.com/search/a%20b%2Fc", SearchDestination({"Path", "path", "https://example.com/search/{query}"}, "a b/c").spec());
  EXPECT_FALSE(shell->UpsertSearchProvider({"Unsafe", "x", "javascript:alert('{query}')"}));
  EXPECT_FALSE(shell->UpsertSearchProvider({"Host substitution", "x", "https://{query}.example.com/"}));
  EXPECT_FALSE(shell->UpsertSearchProvider({"Duplicate", "g", "https://example.com/?q={query}"}));
  EXPECT_FALSE(shell->UpsertSearchProvider({"Twice", "x", "https://example.com/?q={query}&a={query}"}));
  const std::string pattern = embedded_test_server()->GetURL("/").spec() + "storage_probe.html?q={query}";
  ASSERT_TRUE(shell->UpsertSearchProvider({"Local probe", "p", pattern}));
  ASSERT_TRUE(shell->SetDefaultSearchProvider("p"));
  shell->OpenAddress(true); SetPaletteQuery(u"p zażółć & a/b");
  ui::KeyEvent enter(ui::EventType::kKeyPressed, ui::VKEY_RETURN, ui::EF_NONE);
  ASSERT_TRUE(shell->address_input()->view()->OnKeyPressed(enter));
  const auto expected = SearchDestination({"Local probe", "p", pattern}, "zażółć & a/b");
  ASSERT_TRUE(base::test::RunUntil([&] { return window_->contents("work")->GetLastCommittedURL() == expected; }));
  EXPECT_EQ(expected, shell->ResolveInput("zażółć & a/b"));
  ASSERT_TRUE(base::test::RunUntil([&] { return shell->appearance_saved() && window_->configuration_saved(); }));
  window_.reset(); window_ = std::make_unique<WorkspaceWindow>(work_, personal_);
  shell = window_->shell();
  ASSERT_TRUE(base::test::RunUntil([&] { return window_->configuration_ready() && shell->tools_ready(); }));
  EXPECT_EQ(expected, shell->ResolveInput("p zażółć & a/b"));
  EXPECT_EQ(expected, shell->ResolveInput("zażółć & a/b"));
  ASSERT_TRUE(shell->UpsertSearchProvider({"Renamed probe", "probe", pattern}, "p"));
  EXPECT_EQ("probe", shell->browser_tools().default_keyword);
  ASSERT_TRUE(shell->RemoveSearchProvider("probe"));
  EXPECT_NE("probe", shell->browser_tools().default_keyword);
}

IN_PROC_BROWSER_TEST_F(ZitterProfilesBrowserTest, DeveloperModeDetectionAndPersistence) {
  for (const char* url : {"http://localhost:3000/", "https://app.localhost/", "http://localhost./", "http://127.0.0.2:8080/", "http://[::1]:5173/"}) EXPECT_TRUE(IsLocalProject(GURL(url))) << url;
  for (const char* url : {"https://localhost.evil/", "https://evil-localhost/", "https://localhost@evil.test/", "http://128.0.0.1/", "file://localhost/a", "http://192.168.1.1/", "http://[::2]/"}) EXPECT_FALSE(IsLocalProject(GURL(url))) << url;
  auto* shell = window_->shell();
  ASSERT_TRUE(base::test::RunUntil([&]{return shell->tools_ready();}));
  base::DictValue older; base::ListValue keys;
  keys.Append(base::DictValue().Set("id", "reload").Set("chord", "F12"));
  older.Set("shortcuts", std::move(keys));
  const auto migrated = BrowserTools::FromValue(older);
  for (const auto& key : migrated.shortcuts) {
    if (key.id == "reload") EXPECT_EQ(ui::VKEY_F12, key.accelerator.key_code());
    if (key.id == "devtools") EXPECT_EQ(ui::VKEY_UNKNOWN, key.accelerator.key_code());
  }
  EXPECT_EQ("auto", shell->browser_tools().developer_mode);
  EXPECT_EQ("devtools", shell->ShortcutFor(ui::Accelerator(ui::VKEY_F12, 0)));
  auto* control = shell->developer_control_for_testing(); ASSERT_TRUE(control);
  const auto local = embedded_test_server()->GetURL("/storage_probe.html");
  ASSERT_TRUE(content::NavigateToURL(window_->contents("work"), local));
  ASSERT_TRUE(base::test::RunUntil([&]{return control->IsDrawn();}));
  EXPECT_FALSE(DevToolsWindow::GetInstanceForInspectedWebContents(window_->contents("work")));
  shell->SetDeveloperMode("off"); EXPECT_FALSE(control->IsDrawn());
  ASSERT_TRUE(window_->RunShortcut("devtools_console"));
  auto* tools = DevToolsWindow::GetInstanceForInspectedWebContents(window_->contents("work")); ASSERT_TRUE(tools);
  base::test::TestFuture<void> loaded; tools->SetLoadCompletedCallback(loaded.GetCallback()); ASSERT_TRUE(loaded.Wait());
  EXPECT_TRUE(DevToolsWindow::GetInTabWebContents(window_->contents("work"), nullptr));
  EXPECT_FALSE(DevToolsWindowTesting::Get(tools)->browser());
  auto* frontend = DevToolsWindowTesting::Get(tools)->main_web_contents(); ASSERT_TRUE(frontend);
  EXPECT_TRUE(frontend->GetVisibleURL().SchemeIs("devtools"));
  EXPECT_EQ(window_->widget()->GetNativeWindow(), frontend->GetTopLevelNativeWindow());
  EXPECT_EQ(42, content::EvalJs(frontend, "6 * 7"));
  const auto dock = [&](const char* side) {
    ASSERT_TRUE(content::ExecJs(frontend, content::JsReplace(R"(
      (async () => {
        const UI = await import('./ui/legacy/legacy.js');
        UI.DockController.DockController.instance().setDockSide($1);
      })()
    )", side)));
  };
  ASSERT_NO_FATAL_FAILURE(dock("undocked"));
  ASSERT_TRUE(base::test::RunUntil([&] {
    // Chromium keeps a separate device emulation toolbox in the page card
    // while the main frontend is in its own window.
    return DevToolsWindowTesting::Get(tools)->browser() &&
           DevToolsWindow::GetInTabWebContents(window_->contents("work"), nullptr) != frontend;
  }));
  EXPECT_NE(window_->widget()->GetNativeWindow(), frontend->GetTopLevelNativeWindow());
  ASSERT_NO_FATAL_FAILURE(dock("bottom"));
  ASSERT_TRUE(base::test::RunUntil([&] {
    return !DevToolsWindowTesting::Get(tools)->browser() &&
           DevToolsWindow::GetInTabWebContents(window_->contents("work"), nullptr) == frontend;
  }));
  ASSERT_TRUE(base::test::RunUntil([&] {
    const int height = window_->contents("work")->GetRenderWidgetHostView()->GetViewBounds().height();
    return height > 0 && height < window_->widget()->GetWindowBoundsInScreen().height() - 100;
  }));
  content::WebContentsDestroyedWatcher closed(frontend);
  ASSERT_TRUE(window_->RunShortcut("devtools")); closed.Wait();
  // Reopening keeps the user's docking choice and remounts the frontend.
  DevToolsWindowCreationObserver reopened;
  ASSERT_TRUE(window_->RunShortcut("devtools_console")); reopened.WaitForLoad();
  DevToolsContentsResizingStrategy strategy;
  ASSERT_TRUE(DevToolsWindow::GetInTabWebContents(window_->contents("work"), &strategy));
  ASSERT_TRUE(base::test::RunUntil([&] {
    DevToolsWindow::GetInTabWebContents(window_->contents("work"), &strategy);
    return strategy.dock_side() == devtools::DockSide::kBottom;
  }));
  reopened.CloseAllSync();
  shell->SetDeveloperMode("on"); EXPECT_TRUE(control->IsDrawn());
  shell->SetDeveloperMode("auto");
  ASSERT_TRUE(window_->Select("personal"));
  ASSERT_TRUE(base::test::RunUntil([&]{return !control->IsDrawn();}));
  ASSERT_TRUE(window_->Select("work"));
  ASSERT_TRUE(base::test::RunUntil([&]{return control->IsDrawn();}));
  ASSERT_TRUE(window_->RunShortcut("project_split")); EXPECT_TRUE(window_->split());
  auto* focused = window_->contents("work");
  ASSERT_TRUE(content::WaitForLoadStop(focused));
  ASSERT_TRUE(content::ExecJs(focused,"window.dev_reload_marker=42"));
  { content::TestNavigationObserver reloaded(focused); ASSERT_TRUE(window_->RunShortcut("hard_reload")); reloaded.Wait(); }
  EXPECT_EQ("undefined",content::EvalJs(focused,"typeof window.dev_reload_marker"));
  DevToolsWindowCreationObserver created;
  ASSERT_TRUE(window_->RunShortcut("devtools_panel")); created.WaitForLoad();
  EXPECT_TRUE(DevToolsWindow::GetInstanceForInspectedWebContents(focused));
  EXPECT_TRUE(DevToolsWindow::GetInTabWebContents(focused, nullptr));
  EXPECT_FALSE(DevToolsWindow::GetInstanceForInspectedWebContents(window_->pane_contents(false)));
  created.CloseAllSync();
  ASSERT_TRUE(window_->Select("personal")); EXPECT_FALSE(control->IsDrawn());
  ASSERT_TRUE(window_->OpenPeek(local)); ASSERT_TRUE(content::WaitForLoadStop(window_->peek_contents()));
  auto* peek = window_->peek_contents();
  shell->ShowDeveloperMenu(); ASSERT_TRUE(shell->developer_menu_for_testing());
  EXPECT_FALSE(shell->developer_menu_for_testing()->GetIndexOfCommandId(19004));
  if(auto* controller=views::MenuController::GetActiveInstance())controller->Cancel(views::MenuController::ExitType::kAll);
  DevToolsWindowCreationObserver peek_created;
  ASSERT_TRUE(window_->RunShortcut("devtools_panel")); peek_created.WaitForLoad();
  EXPECT_TRUE(DevToolsWindow::GetInstanceForInspectedWebContents(peek));
  EXPECT_TRUE(DevToolsWindow::GetInTabWebContents(peek, nullptr));
  auto* peek_tools=DevToolsWindow::GetInstanceForInspectedWebContents(peek); ASSERT_TRUE(peek_tools);
  content::WebContentsDestroyedWatcher detached(peek_tools->GetDevToolsWebContents());
  window_->ClosePeek(); detached.Wait();
  EXPECT_FALSE(control->IsDrawn());
  ASSERT_TRUE(window_->Select("work")); EXPECT_TRUE(control->IsDrawn());
  shell->ShowDeveloperMenu(); ASSERT_TRUE(shell->developer_menu_for_testing());
  EXPECT_TRUE(shell->developer_menu_for_testing()->GetIndexOfCommandId(19004));
  if(auto* controller=views::MenuController::GetActiveInstance())controller->Cancel(views::MenuController::ExitType::kAll);
  shell->SetDeveloperMode("off"); ASSERT_TRUE(base::test::RunUntil([&]{return shell->appearance_saved();}));
  base::ScopedAllowBlockingForTesting allow;
  std::string json; ASSERT_TRUE(base::ReadFileToString(g_browser_process->profile_manager()->user_data_dir().AppendASCII("ZitterTools.json"), &json));
  auto dict = base::JSONReader::ReadDict(json, base::JSON_PARSE_RFC); ASSERT_TRUE(dict);
  EXPECT_EQ("off", BrowserTools::FromValue(*dict).developer_mode);
}

// Ctrl+scroll reaches the page's delegate as a zoom step; the spelling menu's
// "Language settings" opens Zitter's own spelling preferences.
IN_PROC_BROWSER_TEST_F(ZitterProfilesBrowserTest, PageZoomAndSpellingSettings) {
  ASSERT_TRUE(window_->Select("work"));
  auto* shell = window_->shell();
  ASSERT_TRUE(base::test::RunUntil([&] { return shell->appearance_ready(); }));
  auto* page = window_->contents("work");
  ASSERT_TRUE(content::NavigateToURL(page, embedded_test_server()->GetURL("/storage_probe.html")));
  const double start = content::HostZoomMap::GetZoomLevel(page);
  page->GetDelegate()->ContentsZoomChange(true);
  EXPECT_GT(content::HostZoomMap::GetZoomLevel(page), start);
  page->GetDelegate()->ContentsZoomChange(false);
  page->GetDelegate()->ContentsZoomChange(false);
  EXPECT_LT(content::HostZoomMap::GetZoomLevel(page), start);
  page->GetDelegate()->OpenURLFromTab(page, content::OpenURLParams(GURL("chrome://settings/languages"), content::Referrer(),
      WindowOpenDisposition::NEW_FOREGROUND_TAB, ui::PAGE_TRANSITION_LINK, false), {});
  ASSERT_TRUE(base::test::RunUntil([&] { return shell->general_widget() && shell->general_widget()->IsVisible(); }));
  EXPECT_EQ(u"Sprawdzaj pisownię", shell->preferences_search()->GetText());
  EXPECT_TRUE(shell->preference_toggle("spellcheck")->IsDrawn());
}

// Build the exact upstream editable menu without its platform popup. The
// production WebView deliberately falls through to that menu for edit fields.
class DeveloperEditableMenuForTest : public RenderViewContextMenu {
 public:
  using RenderViewContextMenu::RenderViewContextMenu;
  void Show() override {}
};
IN_PROC_BROWSER_TEST_F(ZitterProfilesBrowserTest, DeveloperInspectFrameAndEditableMenu) {
  auto* shell=window_->shell(); ASSERT_TRUE(base::test::RunUntil([&]{return shell->tools_ready();}));
  auto* page=window_->contents("work");
  const auto local=embedded_test_server()->GetURL("/storage_probe.html");
  ASSERT_TRUE(content::NavigateToURL(page,local));
  ASSERT_TRUE(content::ExecJs(page, "document.body.innerHTML='<iframe srcdoc=\"<input id=inspect-target style=width:200px;height:100px>\"></iframe>'"));
  ASSERT_TRUE(base::test::RunUntil([&]{return content::ChildFrameAt(page->GetPrimaryMainFrame(),0)!=nullptr;}));
  auto* frame=content::ChildFrameAt(page->GetPrimaryMainFrame(),0); ASSERT_TRUE(frame);
  ASSERT_TRUE(content::WaitForLoadStop(page));
  content::ContextMenuParams params; params.page_url=local; params.frame_url=frame->GetLastCommittedURL();params.is_editable=true;
  // Context-menu points are in root CSS coordinates, even for a subframe.
  params.x=content::EvalJs(page,"Math.round(document.querySelector('iframe').getBoundingClientRect().left + 20)").ExtractInt();
  params.y=content::EvalJs(page,"Math.round(document.querySelector('iframe').getBoundingClientRect().top + 20)").ExtractInt();
  params.edit_flags=blink::ContextMenuDataEditFlags::kCanCopy | blink::ContextMenuDataEditFlags::kCanPaste | blink::ContextMenuDataEditFlags::kCanSelectAll;
  EXPECT_FALSE(page->GetDelegate()->HandleContextMenu(*frame,params));
  DeveloperEditableMenuForTest editable(*frame,params,true,true); editable.Init();
  EXPECT_TRUE(editable.menu_model().GetIndexOfCommandId(IDC_CONTENT_CONTEXT_COPY));
  EXPECT_TRUE(editable.menu_model().GetIndexOfCommandId(IDC_CONTENT_CONTEXT_PASTE));
  EXPECT_TRUE(editable.menu_model().GetIndexOfCommandId(IDC_CONTENT_CONTEXT_INSPECTELEMENT));
  EXPECT_TRUE(editable.IsCommandIdEnabled(IDC_CONTENT_CONTEXT_INSPECTELEMENT));
  DevToolsWindowCreationObserver created;
  editable.ExecuteCommand(IDC_CONTENT_CONTEXT_INSPECTELEMENT,0); created.WaitForLoad();
  auto* tools=DevToolsWindow::GetInstanceForInspectedWebContents(page); ASSERT_TRUE(tools);
  auto* frontend=tools->GetDevToolsWebContents().get(); ASSERT_TRUE(frontend);
  EXPECT_EQ("inspect-target",content::EvalJs(frontend,R"JS((async()=>{
    const m=await import('./panels/elements/elements.js');
    for(let i=0;i<100;i++) {
      const node=m.ElementsPanel.ElementsPanel.instance().selectedDOMNode();
      if(node?.getAttribute('id')==='inspect-target')return node.getAttribute('id');
      await new Promise(r=>setTimeout(r,50));
    }
    return 'no selected target';
  })())JS"));
  created.CloseAllSync();
  params.is_editable=false;
  EXPECT_TRUE(page->GetDelegate()->HandleContextMenu(*frame,params));
  auto* menu=shell->page_context_menu_for_testing();ASSERT_TRUE(menu);ASSERT_TRUE(menu->GetIndexOfCommandId(19010));
  if(auto* controller=views::MenuController::GetActiveInstance())controller->Cancel(views::MenuController::ExitType::kAll);
  // The custom menu binds the document, so a stale click after navigation is inert.
  ASSERT_TRUE(content::NavigateToURL(page,local.Resolve("?replacement")));
  menu->ActivatedAt(*menu->GetIndexOfCommandId(19010),0);base::RunLoop().RunUntilIdle();
  EXPECT_FALSE(DevToolsWindow::GetInstanceForInspectedWebContents(page));
  work_->GetPrefs()->SetInteger(prefs::kDevToolsAvailability,static_cast<int>(policy::DeveloperToolsAvailability::kDisallowed));
  EXPECT_FALSE(window_->RunShortcut("devtools_panel"));
  EXPECT_FALSE(DevToolsWindow::GetInstanceForInspectedWebContents(page));
  work_->GetPrefs()->ClearPref(prefs::kDevToolsAvailability);
}

