// Context menus run as Views menus (design: ContextMenu): open one, inspect it
// while it runs, then close it.
bool RunWithMenuInspection(WorkspaceShell* shell,base::OnceClosure open,base::RepeatingClosure inspect){
  std::move(open).Run();
  if(!base::test::RunUntil([&]{return shell->workspace_context_menu_running_for_testing();}))return false;
  inspect.Run();shell->CancelContextMenuForTesting();
  return base::test::RunUntil([&]{return !shell->workspace_context_menu_running_for_testing();});
}

// Context menus (design: ContextMenu): the destructive action reads in danger,
// last, after a separator.
IN_PROC_BROWSER_TEST_F(ZitterProfilesBrowserTest, ContextMenusMarkDestructiveActionsInDanger) {
  auto* shell=window_->shell();ASSERT_TRUE(base::test::RunUntil([&]{return shell->appearance_ready();}));
  shell->BuildWorkspaceMenu("personal");auto* menu=shell->workspace_menu();ASSERT_TRUE(menu);
  const auto last=menu->GetItemCount()-1;EXPECT_EQ(u"Usuń przestrzeń",menu->GetLabelAt(last));
  EXPECT_EQ(ui::MenuModel::TYPE_SEPARATOR,menu->GetTypeAt(last-1));
  EXPECT_EQ(std::optional<ui::ColorId>(ui::kColorAlertHighSeverity),menu->GetForegroundColorId(last));
  EXPECT_EQ(std::nullopt,menu->GetForegroundColorId(last-2));
  EXPECT_EQ(shell->workspace_menu()->GetLabelAt(last-2),u"Ustawienia przestrzeni");
}

IN_PROC_BROWSER_TEST_F(ZitterProfilesBrowserTest, EmptySidebarOpensActiveWorkspaceMenu) {
  auto* shell = window_->shell();
  ASSERT_TRUE(base::test::RunUntil([&] { return shell->appearance_ready(); }));
  ASSERT_TRUE(window_->Select("work"));
  shell->SetPinned(true);
  shell->ShowSidebar();
  shell->sidebar_widget()->LayoutRootViewIfNecessary();
  const auto inspect = base::BindRepeating([](WorkspaceShell* shell) {
    const auto* menu = shell->workspace_menu();
    ASSERT_TRUE(menu);
    EXPECT_EQ(u"Nowy folder", menu->GetLabelAt(3));
    for (size_t i = 0; i < menu->GetItemCount(); ++i)
      EXPECT_NE(u"Live Folders", menu->GetLabelAt(i));
    const auto* profiles = menu->GetSubmenuModelAt(0);
    ASSERT_TRUE(profiles);
    EXPECT_TRUE(profiles->IsItemCheckedAt(0));
    EXPECT_FALSE(profiles->IsItemCheckedAt(1));
  }, base::Unretained(shell));
  for (auto* target : {shell->workspace_button("work"), shell->sidebar_view()}) {
    ASSERT_TRUE(target);
    EXPECT_TRUE(RunWithMenuInspection(shell, base::BindOnce([](views::View* view) {
      view->ShowContextMenu(view->GetBoundsInScreen().CenterPoint(),
                            ui::mojom::MenuSourceType::kMouse);
    }, base::Unretained(target)), inspect));
  }
  shell->BuildWorkspaceMenu("work");
  auto* menu = shell->workspace_menu();
  ASSERT_TRUE(menu->IsEnabledAt(3));
  menu->ActivatedAt(3);
  ASSERT_TRUE(base::test::RunUntil([&] { return shell->folder_dialog() != nullptr; }));
  shell->folder_dialog()->CloseNow();
  ASSERT_TRUE(base::test::RunUntil([&] { return shell->folder_dialog() == nullptr; }));
}

// Space panel (design: space settings): the name saves itself, a profile row
// switches the space at once (the pressed row is rebuilt), and a new space can
// make its own profile.
IN_PROC_BROWSER_TEST_F(ZitterProfilesBrowserTest, SpacePanelAutosavesAndMakesProfileWithNewSpace) {
  auto* shell=window_->shell();ASSERT_TRUE(base::test::RunUntil([&]{return shell->appearance_ready();}));
  ASSERT_TRUE(window_->Select("work"));shell->OpenWorkspaceSettings();
  ASSERT_EQ(window_->profiles().size()+1,shell->workspace_profile_row_count());
  // Typing commits text; the name saves once typing pauses.
  auto* field=shell->workspace_input();field->RequestFocus();field->SelectRange(gfx::Range(field->GetText().size()));
  field->input_client()->InsertText(u" nowa",ui::TextInputClient::InsertTextCursorBehavior::kMoveCursorAfterText);
  ASSERT_TRUE(base::test::RunUntil([&]{return window_->workspaces()[0].name==base::UTF16ToUTF8(field->GetText())&&window_->workspaces()[0].name.ends_with(" nowa");}));EXPECT_TRUE(shell->workspace_saved_visible());
  size_t other=0;for(size_t i=0;i<window_->profiles().size();++i)if(window_->profiles()[i].id!="work-profile")other=i;
  ui::AXActionData activate;activate.action=ax::mojom::Action::kDoDefault;
  ASSERT_TRUE(shell->workspace_profile_row(other)->HandleAccessibleAction(activate));
  ASSERT_TRUE(base::test::RunUntil([&]{return window_->workspaces()[0].profile_id==window_->profiles()[other].id&&!window_->profiles_busy();}));
  base::RunLoop().RunUntilIdle();
  ASSERT_EQ(window_->profiles().size()+1,shell->workspace_profile_row_count());
  const auto profiles=window_->profiles().size();const auto spaces=window_->workspaces().size();
  shell->StartWorkspaceCreationForTesting();ASSERT_TRUE(shell->creating_workspace_for_testing());
  shell->workspace_input()->SetText(u"Klient X");
  // „Nowy profil” is the list's last row, below the fold of a short window.
  shell->settings_widget()->LayoutRootViewIfNecessary();auto* last=shell->workspace_profile_row(shell->workspace_profile_row_count()-1);last->ScrollViewToVisible();
  ASSERT_TRUE(last->HandleAccessibleAction(activate));
  ASSERT_TRUE(base::test::RunUntil([&]{return shell->new_profile_input()->view()->IsDrawn();}));EXPECT_EQ(u"Klient X",shell->new_profile_input()->GetText());
  ASSERT_TRUE(FindButton(shell->workspace_panel_for_testing(),u"Utwórz przestrzeń i profil"));
  ClickControl(FindButton(shell->workspace_panel_for_testing(),u"Utwórz przestrzeń i profil"));
  ASSERT_TRUE(base::test::RunUntil([&]{return window_->workspaces().size()==spaces+1&&window_->profiles().size()==profiles+1&&!window_->profiles_busy();}));
  EXPECT_EQ("Klient X",window_->workspaces().back().name);EXPECT_EQ("Klient X",window_->profiles().back().name);
  ASSERT_TRUE(base::test::RunUntil([&]{return window_->workspaces().back().profile_id==window_->profiles().back().id;}));
}

// Removing a space asks first; Cancel keeps it.
IN_PROC_BROWSER_TEST_F(ZitterProfilesBrowserTest, SpaceRemovalAsksFirst) {
  auto* shell=window_->shell();ASSERT_TRUE(base::test::RunUntil([&]{return shell->appearance_ready();}));
  const auto spaces=window_->workspaces().size();
  shell->RequestRemoveWorkspace("personal");ASSERT_TRUE(shell->workspace_remove_dialog());
  shell->workspace_remove_dialog()->widget_delegate()->AsDialogDelegate()->CancelDialog();
  ASSERT_TRUE(base::test::RunUntil([&]{return !shell->workspace_remove_dialog();}));EXPECT_EQ(spaces,window_->workspaces().size());
  shell->RequestRemoveWorkspace("personal");ASSERT_TRUE(AcceptWorkspaceRemoval(shell));
  ASSERT_TRUE(base::test::RunUntil([&]{return window_->workspaces().size()==spaces-1;}));
}
// A tab dragged onto the page lands at the nearest pane edge (design: SplitView).
IN_PROC_BROWSER_TEST_F(ZitterProfilesBrowserTest, SplitDropSlotFollowsThePointer) {
  ASSERT_NO_FATAL_FAILURE(NavigateBoth());
  auto* shell=window_->shell();ASSERT_TRUE(base::test::RunUntil([&]{return shell->appearance_ready();}));
  ASSERT_TRUE(window_->Select("work"));window_->widget()->LayoutRootViewIfNecessary();
  auto at=[&](double along){const auto b=shell->content_host()->GetBoundsInScreen();return shell->SplitDropSlotForTesting(gfx::Point(b.x()+static_cast<int>(b.width()*along),b.CenterPoint().y()));};
  EXPECT_EQ(0u,at(0.2));EXPECT_EQ(1u,at(0.8));EXPECT_FALSE(shell->SplitDropSlotForTesting(gfx::Point(-50,-50)));
  const auto url=embedded_test_server()->GetURL("/storage_probe.html?drop");ASSERT_TRUE(window_->NavigateFromBar(url,true));window_->SelectTab(0);ASSERT_TRUE(window_->SplitTab(1));window_->widget()->LayoutRootViewIfNecessary();
  EXPECT_EQ(0u,at(0.1));EXPECT_EQ(1u,at(0.5));EXPECT_EQ(2u,at(0.9));
  // A drop in the middle walks the new pane between the two.
  ASSERT_TRUE(window_->NavigateFromBar(embedded_test_server()->GetURL("/storage_probe.html?third"),true));
  const size_t third=window_->tab_count("work")-1;window_->SelectTab(0);
  ASSERT_EQ(2u,shell->split_tabs_for_testing().size());shell->DropIntoSplitForTesting(third,1);
  ASSERT_TRUE(base::test::RunUntil([&]{return shell->split_tabs_for_testing().size()==3u;}));EXPECT_EQ(third,shell->split_tabs_for_testing()[1]);
}

// A pane's bar dragged within the page moves the pane; dropped on the sidebar
// it takes the tab out of the split, like dragging its row out of the pair.
IN_PROC_BROWSER_TEST_F(ZitterProfilesBrowserTest, SplitPaneDragMovesOrLeavesTheSplit) {
  ASSERT_NO_FATAL_FAILURE(NavigateBoth());
  auto* shell=window_->shell();ASSERT_TRUE(base::test::RunUntil([&]{return shell->appearance_ready();}));ASSERT_TRUE(window_->Select("work"));
  ASSERT_TRUE(window_->NavigateFromBar(embedded_test_server()->GetURL("/storage_probe.html?pane"),true));window_->SelectTab(0);ASSERT_TRUE(window_->SplitTab(1));
  shell->CloseOverlays(true);shell->SetPinned(true);shell->ShowSidebar();shell->sidebar_widget()->LayoutRootViewIfNecessary();window_->widget()->LayoutRootViewIfNecessary();
  ASSERT_EQ((std::vector<size_t>{0,1}),shell->split_tabs_for_testing());
  const auto b=shell->content_host()->GetBoundsInScreen();const gfx::Point left(b.x()+b.width()/10,b.CenterPoint().y());
  shell->PaneDragForTesting(1,left,false);EXPECT_EQ(std::optional<size_t>(0),shell->split_drop_slot_for_testing());
  shell->PaneDragForTesting(1,left,true);ASSERT_TRUE(base::test::RunUntil([&]{return shell->split_tabs_for_testing()==std::vector<size_t>{1,0};}));
  const gfx::Point row=shell->tab_button(1)->GetBoundsInScreen().CenterPoint();
  shell->PaneDragForTesting(0,row,false);EXPECT_TRUE(shell->sidebar_drop_target_for_testing());
  shell->PaneDragForTesting(0,row,true);EXPECT_FALSE(shell->sidebar_drop_target_for_testing());
  ASSERT_TRUE(base::test::RunUntil([&]{return shell->split_tabs_for_testing().size()<2u;}));
}
