essibility().GetAccessibleNodeData(&ax);EXPECT_NE(std::u16string::npos,ax.GetString16Attribute(ax::mojom::StringAttribute::kName).find(u"Zezwalaj"));EXPECT_TRUE(remove->GetEnabled());
