IN_PROC_BROWSER_TEST_F(ZitterProfilesBrowserTest, CmdClickOpensBackgroundTabWithToast) {
  const auto source_url = embedded_test_server()->GetURL("/links_probe.html");
  const auto target = embedded_test_server()->GetURL("/storage_probe.html?peek");
  ASSERT_TRUE(window_->Select("work"));
  ASSERT_TRUE(content::NavigateToURL(window_->contents("work"), source_url));
  auto* source = window_->contents("work");
  content::SimulateEndOfPaintHoldingOnPrimaryMainFrame(source);
#if BUILDFLAG(IS_MAC)
  constexpr int modifier = blink::WebInputEvent::kMetaKey;
#else
  constexpr int modifier = blink::WebInputEvent::kControlKey;
#endif
  const size_t tabs = window_->tab_count("work");
  content::SimulateMouseClickAt(source, modifier, blink::WebMouseEvent::Button::kLeft,
      gfx::ToRoundedPoint(content::GetCenterCoordinatesOfElementWithId(source, "peek")));
  ASSERT_TRUE(base::test::RunUntil([&] { return window_->tab_count("work") == tabs + 1; }));
  EXPECT_EQ(nullptr, window_->peek_contents());           // No mini window any more.
  EXPECT_EQ(source, window_->contents("work"));           // The page stays in front.
  auto* shell = window_->shell();
  ASSERT_TRUE(shell->toast_widget()->IsVisible());
  // The toast's Pokaż switches to the new tab, which loaded in the background.
  shell->UndoToast();
  ASSERT_NE(source, window_->contents("work"));
  ASSERT_TRUE(content::WaitForLoadStop(window_->contents("work")));
  EXPECT_EQ(target, window_->contents("work")->GetLastCommittedURL());
}

IN_PROC_BROWSER_TEST_F(ZitterProfilesBrowserTest, ShiftClickOpensPeekAndPromotesExistingPage) {
  const auto source_url = embedded_test_server()->GetURL("/links_probe.html");
  const auto target = embedded_test_server()->GetURL("/storage_probe.html?peek");
  auto* source = window_->contents("work");
  ASSERT_TRUE(content::NavigateToURL(source, source_url));
  ASSERT_TRUE(content::ExecJs(source, "document.getElementById('marker').value = 'kept'"));
  content::SimulateEndOfPaintHoldingOnPrimaryMainFrame(source);
  EXPECT_EQ(1, window_->ReadPreferences().at("shift_click_peek").value);
  const auto tabs = window_->tab_count("work");
  content::SimulateMouseClickAt(source, blink::WebInputEvent::kShiftKey, blink::WebMouseEvent::Button::kLeft,
      gfx::ToRoundedPoint(content::GetCenterCoordinatesOfElementWithId(source, "peek")));
  ASSERT_TRUE(base::test::RunUntil([&] { return window_->peek_contents() != nullptr; }));
  auto* peek = window_->peek_contents();
  ASSERT_TRUE(content::WaitForLoadStop(peek));
  EXPECT_EQ(target, peek->GetLastCommittedURL());
  EXPECT_EQ(tabs, window_->tab_count("work"));
  EXPECT_EQ(source_url, source->GetLastCommittedURL());
  EXPECT_EQ("kept", content::EvalJs(source, "document.getElementById('marker').value"));
  ASSERT_TRUE(content::ExecJs(peek, "document.getElementById('marker').value = 'peek state'"));
  ASSERT_TRUE(window_->PromotePeek(false));
  EXPECT_EQ(peek, window_->contents("work"));
  EXPECT_EQ(tabs + 1, window_->tab_count("work"));
  EXPECT_EQ("peek state", content::EvalJs(peek, "document.getElementById('marker').value"));
  ASSERT_TRUE(content::NavigateToURL(peek, source_url));
  content::SimulateEndOfPaintHoldingOnPrimaryMainFrame(peek);
  const auto blank = gfx::ToRoundedPoint(content::GetCenterCoordinatesOfElementWithId(peek, "blank"));
  content::SimulateMouseEvent(peek, blink::WebInputEvent::Type::kMouseMove, blank);
  content::SimulateMouseClickAt(peek, blink::WebInputEvent::kShiftKey, blink::WebMouseEvent::Button::kLeft, blank);
  ASSERT_TRUE(base::test::RunUntil([&] { return window_->peek_contents() != nullptr; }));
  ASSERT_TRUE(content::WaitForLoadStop(window_->peek_contents()));
  EXPECT_EQ(embedded_test_server()->GetURL("/storage_probe.html?blank"), window_->peek_contents()->GetLastCommittedURL());
  EXPECT_EQ(tabs + 1, window_->tab_count("work"));
  window_->ClosePeek();
  ASSERT_TRUE(window_->WritePreference("shift_click_peek", 0));
  content::SimulateMouseClickAt(peek, blink::WebInputEvent::kShiftKey, blink::WebMouseEvent::Button::kLeft,
      gfx::ToRoundedPoint(content::GetCenterCoordinatesOfElementWithId(peek, "peek")));
  ASSERT_TRUE(base::test::RunUntil([&] { return window_->tab_count("work") == tabs + 2; }));
  EXPECT_EQ(nullptr, window_->peek_contents());
}

IN_PROC_BROWSER_TEST_F(ZitterProfilesBrowserTest, ImageLinkPreviewOptInAndCancellation) {
  EXPECT_TRUE(ImageLinkPreview::IsImageURL(GURL("https://example.test/photo.JPG?size=100#image")));
  EXPECT_FALSE(ImageLinkPreview::IsImageURL(GURL("https://example.test/page?image=x.png")));
  EXPECT_FALSE(ImageLinkPreview::IsImageURL(GURL("https://user:password@example.test/x.png")));
  EXPECT_FALSE(ImageLinkPreview::IsImageURL(GURL("file:///tmp/x.png")));
  EXPECT_FALSE(ImageLinkPreview::IsImageURL(GURL("javascript:alert('x.png')")));
  auto* page = window_->contents("work");
  ASSERT_TRUE(content::NavigateToURL(page, embedded_test_server()->GetURL("/links_probe.html")));
  ASSERT_TRUE(ui_test_utils::ShowAndFocusNativeWindow(window_->widget()->GetNativeWindow()));
  content::SimulateEndOfPaintHoldingOnPrimaryMainFrame(page);
  const auto image = embedded_test_server()->GetURL("/preview_image.svg?hover=1");
  EXPECT_EQ(0, window_->ReadPreferences().at("image_link_previews").value);
  page->GetDelegate()->UpdateTargetURL(page, image);
  EXPECT_FALSE(window_->image_preview_visible_for_testing(page));
  ASSERT_TRUE(window_->WritePreference("image_link_previews", 1));
  ASSERT_TRUE(content::ExecJs(page, "document.getElementById('image').scrollIntoView({block: 'center'})"));
  content::SimulateMouseEvent(page, blink::WebInputEvent::Type::kMouseMove,
      gfx::ToRoundedPoint(content::GetCenterCoordinatesOfElementWithId(page, "image")));
  ASSERT_TRUE(base::test::RunUntil([&] { return window_->image_preview_visible_for_testing(page); }));
  EXPECT_EQ(page, window_->contents("work"));
  EXPECT_TRUE(window_->widget()->IsActive());
  page->GetDelegate()->UpdateTargetURL(page, GURL());
  EXPECT_FALSE(window_->image_preview_visible_for_testing(page));
  // Leaving and re-entering cancels the old download generation, even for the same URL.
  page->GetDelegate()->UpdateTargetURL(page, image);
  page->GetDelegate()->UpdateTargetURL(page, GURL());
  page->GetDelegate()->UpdateTargetURL(page, image);
  ASSERT_TRUE(base::test::RunUntil([&] { return window_->image_preview_visible_for_testing(page); }));
  ASSERT_TRUE(window_->WritePreference("image_link_previews", 0));
  EXPECT_FALSE(window_->image_preview_visible_for_testing(page));
  EXPECT_FALSE(window_->WritePreference("image_link_previews", 2));
  ASSERT_TRUE(window_->WritePreference("image_link_previews", 1));
  page->GetDelegate()->UpdateTargetURL(page, image);
  ASSERT_TRUE(base::test::RunUntil([&] { return window_->image_preview_visible_for_testing(page); }));
  ASSERT_TRUE(window_->Select("personal"));
  EXPECT_FALSE(window_->image_preview_visible_for_testing(page));
}

IN_PROC_BROWSER_TEST_F(ZitterProfilesBrowserTest, LinkPreviewPreferencesSurviveWindowRecreation) {
  ASSERT_TRUE(window_->WritePreference("image_link_previews", 1));
  ASSERT_TRUE(window_->WritePreference("shift_click_peek", 0));
  ASSERT_TRUE(base::test::RunUntil([&] { return window_->configuration_saved(); }));
  window_.reset();
  window_ = std::make_unique<WorkspaceWindow>(work_, personal_);
  ASSERT_TRUE(base::test::RunUntil([&] { return window_->configuration_ready(); }));
  EXPECT_EQ(1, window_->ReadPreferences().at("image_link_previews").value);
  EXPECT_EQ(0, window_->ReadPreferences().at("shift_click_peek").value);
  ASSERT_TRUE(window_->Select("personal"));
  EXPECT_EQ(1, window_->ReadPreferences().at("image_link_previews").value);
  EXPECT_EQ(0, window_->ReadPreferences().at("shift_click_peek").value);
}

IN_PROC_BROWSER_TEST_F(ZitterProfilesBrowserTest, PeekLifecycleAndPromotion) {
  const auto source_url = embedded_test_server()->GetURL("/links_probe.html");
  const auto target = embedded_test_server()->GetURL("/storage_probe.html?peek");
  ASSERT_TRUE(content::NavigateToURL(window_->contents("work"), source_url));
  auto* source = window_->contents("work");
  ASSERT_TRUE(content::ExecJs(source, "document.getElementById('marker').value = 'source kept'"));
  content::SimulateEndOfPaintHoldingOnPrimaryMainFrame(source);
  // Cmd+click opens a background tab (CmdClickOpensBackgroundTabWithToast); Peek
  // still opens from the link menu.
  ASSERT_TRUE(window_->OpenPeek(target));
  auto* peek = window_->peek_contents();
  ASSERT_TRUE(content::WaitForLoadStop(peek));
  EXPECT_EQ(target, peek->GetLastCommittedURL());
  EXPECT_EQ(work_.get(), peek->GetBrowserContext());
  EXPECT_EQ(1u, window_->tab_count("work"));
  EXPECT_EQ(source_url, source->GetLastCommittedURL());
  EXPECT_EQ("source kept", content::EvalJs(source, "document.getElementById('marker').value"));
  ASSERT_TRUE(content::ExecJs(peek, "document.getElementById('marker').value = 'peek kept'"));
  ASSERT_TRUE(window_->PromotePeek(false));
  EXPECT_EQ(nullptr, window_->peek_contents());
  EXPECT_FALSE(window_->shell()->peek_widget()->IsVisible());
  EXPECT_EQ(peek, window_->contents("work"));
  EXPECT_EQ(2u, window_->tab_count("work"));
  EXPECT_EQ("peek kept", content::EvalJs(peek, "document.getElementById('marker').value"));
  ASSERT_TRUE(window_->OpenPeek(target));
  auto* second = window_->peek_contents();
  ASSERT_TRUE(content::WaitForLoadStop(second));
  ASSERT_TRUE(window_->PromotePeek(true));
  EXPECT_TRUE(window_->split());
  EXPECT_EQ(peek, window_->pane_contents(false));
  EXPECT_EQ(second, window_->pane_contents(true));
  ASSERT_TRUE(window_->OpenPeek(target));
  ASSERT_TRUE(content::WaitForLoadStop(window_->peek_contents()));
  EnableNativeUIControls();
  ASSERT_TRUE(ui_test_utils::ShowAndFocusNativeWindow(window_->shell()->peek_widget()->GetNativeWindow()));
  ASSERT_TRUE(ui_test_utils::SendKeyPressToWindowSync(window_->shell()->peek_widget()->GetNativeWindow(),
      ui::VKEY_ESCAPE, false, false, false, false));
  ASSERT_TRUE(base::test::RunUntil([&] { return !window_->peek_contents(); }));
  EXPECT_EQ(3u, window_->tab_count("work"));
  ASSERT_TRUE(window_->OpenPeek(target));
  ASSERT_TRUE(window_->Select("personal"));
  EXPECT_EQ(nullptr, window_->peek_contents());
  EXPECT_EQ(1u, window_->tab_count("personal"));
  // A real target=_blank link is hosted as a Zitter tab.
  ASSERT_TRUE(content::NavigateToURL(window_->contents("personal"), source_url));
  ASSERT_TRUE(content::ExecJs(window_->contents("personal"), "document.getElementById('blank').click()"));
  ASSERT_TRUE(base::test::RunUntil([&] { return window_->tab_count("personal") == 2; }));
  ASSERT_TRUE(base::test::RunUntil([&] {
    return window_->contents("personal")->GetLastCommittedURL() == embedded_test_server()->GetURL("/storage_probe.html?blank");
  }));
}

IN_PROC_BROWSER_TEST_F(ZitterProfilesBrowserTest, DomainRoutingAndPersistence) {
  const auto source_url = embedded_test_server()->GetURL("/links_probe.html");
  const auto target = embedded_test_server()->GetURL("client.test", "/storage_probe.html?routed");
  ASSERT_TRUE(content::NavigateToURL(window_->contents("work"), target));
  ASSERT_EQ("work", content::EvalJs(window_->contents("work"), "writeMarker('work')"));
  ASSERT_TRUE(window_->Select("personal"));
  ASSERT_TRUE(content::NavigateToURL(window_->contents("personal"), target));
  ASSERT_EQ("personal", content::EvalJs(window_->contents("personal"), "writeMarker('personal')"));
  ASSERT_TRUE(window_->Select("work"));
  ASSERT_TRUE(content::NavigateToURL(window_->contents("work"), source_url));
  auto* source = window_->contents("work");
  { base::AutoLock guard(routing_lock_); routing_cookies_.clear(); }
  auto* shell = window_->shell();
  shell->BuildLinkMenu(target, "work");
  // New tab, Peek, Split View, then the routes submenu.
  auto* rules = shell->link_menu()->GetSubmenuModelAt(3);
  ASSERT_TRUE(rules); rules->ActivatedAt(1, 0);
  ASSERT_TRUE(base::test::RunUntil([&] { return window_->WorkspaceForUrl(target) == "personal"; }));
  EXPECT_FALSE(window_->SetLinkRule(GURL("file:///tmp/x"), "personal"));
  EXPECT_FALSE(window_->SetLinkRule(target, "missing"));
  EXPECT_TRUE(window_->WorkspaceForUrl(GURL("https://sub.client.test/")).empty());
  shell->BuildLinkMenu(target, "work");
  EXPECT_TRUE(shell->link_menu()->GetSubmenuModelAt(3)->IsItemCheckedAt(1));
  // Routes, a separator, „Zawsze otwieraj … w …”, then the rule's removal.
  shell->link_menu()->GetSubmenuModelAt(3)->ActivatedAt(4, 0);
  ASSERT_TRUE(base::test::RunUntil([&] { return window_->WorkspaceForUrl(target).empty(); }));
  ASSERT_TRUE(window_->SetLinkRule(target, "personal"));
  ASSERT_TRUE(content::ExecJs(source, content::JsReplace("document.getElementById('route').href = $1; document.getElementById('route').click()", target)));
  ASSERT_TRUE(base::test::RunUntil([&] { return window_->active_id() == "personal" && window_->contents("personal")->GetLastCommittedURL() == target; }));
  ASSERT_TRUE(content::WaitForLoadStop(window_->contents("personal")));
  EXPECT_EQ("personal|personal|personal|", content::EvalJs(window_->contents("personal"), "readMarker()"));
  EXPECT_EQ(source_url, source->GetLastCommittedURL());
  {
    base::AutoLock guard(routing_lock_);
    ASSERT_EQ(1u, routing_cookies_.size());
    EXPECT_NE(std::string::npos, routing_cookies_[0].find("zitter=personal"));
    EXPECT_EQ(std::string::npos, routing_cookies_[0].find("zitter=work"));
  }
  ASSERT_TRUE(window_->Select("work"));
  ASSERT_TRUE(content::ExecJs(source, content::JsReplace("document.getElementById('blank').href = $1; document.getElementById('blank').click()", target)));
  ASSERT_TRUE(base::test::RunUntil([&] { return window_->active_id() == "personal" && window_->tab_count("work") == 1; }));
  ASSERT_TRUE(window_->Select("work"));
  ASSERT_TRUE(window_->OpenPeek(target));
  EXPECT_EQ("work", window_->active_id());
  ASSERT_TRUE(content::WaitForLoadStop(window_->peek_contents()));
  EXPECT_EQ(personal_.get(), window_->peek_contents()->GetBrowserContext());
  EXPECT_EQ("personal|personal|personal|", content::EvalJs(window_->peek_contents(), "readMarker()"));
  ASSERT_TRUE(window_->PromotePeek(false));
  EXPECT_EQ("personal", window_->active_id());
  ASSERT_TRUE(base::test::RunUntil([&] { return window_->configuration_saved(); }));
  window_.reset(); window_ = std::make_unique<WorkspaceWindow>(work_, personal_);
  ASSERT_TRUE(base::test::RunUntil([&] { return window_->configuration_ready(); }));
  EXPECT_EQ("personal", window_->WorkspaceForUrl(target));
  ASSERT_TRUE(window_->Select("work"));
  ASSERT_TRUE(window_->OpenExternalUrl(target));
  EXPECT_EQ("personal", window_->active_id());
  EXPECT_EQ(personal_.get(), window_->contents("personal")->GetBrowserContext());
  ASSERT_TRUE(window_->AssignProfile("personal", "work-profile"));
  ASSERT_TRUE(window_->Select("work"));
  ASSERT_TRUE(window_->OpenExternalUrl(target));
  EXPECT_EQ("personal", window_->active_id());
  EXPECT_EQ(work_.get(), window_->contents("personal")->GetBrowserContext());
  // Removing a target also removes its routing rule, never a dangling profile.
  ASSERT_TRUE(window_->RemoveWorkspace());
  EXPECT_TRUE(window_->WorkspaceForUrl(target).empty());
  EXPECT_TRUE(window_->link_rules().empty());
}

IN_PROC_BROWSER_TEST_F(ZitterProfilesBrowserTest, RoutingLeavesFormsFramesAndRedirects) {
  const auto source_url = embedded_test_server()->GetURL("/links_probe.html");
  const auto frame_url = embedded_test_server()->GetURL("client.test", "/storage_probe.html?frame");
  const auto post_url = embedded_test_server()->GetURL("client.test", "/login-success");
  ASSERT_TRUE(window_->SetLinkRule(frame_url, "personal"));
  ASSERT_TRUE(content::NavigateToURL(window_->contents("work"), source_url));
  auto* source = window_->contents("work");
  ASSERT_TRUE(content::ExecJs(source, content::JsReplace(
      "const frame = document.createElement('iframe'); frame.src = $1; document.body.append(frame)", frame_url)));
  ASSERT_TRUE(base::test::RunUntil([&] {
    auto* frame = content::ChildFrameAt(source->GetPrimaryMainFrame(), 0);
    return frame && frame->GetLastCommittedURL() == frame_url;
  }));
  EXPECT_EQ("work", window_->active_id());
  ASSERT_TRUE(content::ExecJs(source, content::JsReplace(
      "const form = document.createElement('form'); form.action = $1; form.method = 'post'; document.body.append(form); form.requestSubmit()", post_url)));
  ASSERT_TRUE(base::test::RunUntil([&] { return source->GetLastCommittedURL() == post_url; }));
  EXPECT_EQ("work", window_->active_id());
  EXPECT_EQ(work_.get(), source->GetBrowserContext());
  EXPECT_EQ(1u, window_->tab_count("personal"));
  ASSERT_TRUE(content::NavigateToURL(source, source_url));
  ASSERT_TRUE(content::ExecJs(source, "document.getElementById('route').href = '/route-redirect'; document.getElementById('route').click()"));
  ASSERT_TRUE(base::test::RunUntil([&] {
    return source->GetLastCommittedURL() == embedded_test_server()->GetURL("client.test", "/storage_probe.html?redirect");
  }));
  EXPECT_EQ("work", window_->active_id());
  EXPECT_EQ(work_.get(), source->GetBrowserContext());
  EXPECT_EQ(1u, window_->tab_count("personal"));
}

IN_PROC_BROWSER_TEST_F(ZitterProfilesBrowserTest, DownloadsTransferControlsAndProfileIsolation) {
  base::ScopedAllowBlockingForTesting test_files;
  base::test::ScopedRunLoopTimeout timeout(FROM_HERE, base::Seconds(30));
  NavigateBoth();
  ASSERT_TRUE(window_->Select("work"));
  base::ScopedTempDir directory;
  ASSERT_TRUE(directory.CreateUniqueTempDir());
  DownloadPrefs::FromBrowserContext(work_)->SetDownloadPath(directory.GetPath());
  work_->GetPrefs()->SetBoolean(prefs::kPromptForDownload, false);
  auto* manager = work_->GetDownloadManager();
  net::EmbeddedTestServer server;
  net::test_server::ControllableHttpResponse stream(&server, "/transfer.txt");
  net::test_server::ControllableHttpResponse cancelled(&server, "/cancel.txt");
  ASSERT_TRUE(server.Start());
  window_->ShowDownloads();
  auto* panel = window_->downloads();
  ASSERT_TRUE(panel && panel->widget() && panel->widget()->IsVisible());
  EXPECT_EQ(ui::mojom::ModalType::kNone, panel->widget()->widget_delegate()->GetModalType());
  const auto area = display::Screen::Get()->GetDisplayNearestWindow(window_->widget()->GetNativeWindow()).work_area();
  EXPECT_TRUE(area.Contains(panel->widget()->GetWindowBoundsInScreen()));
  auto start = [&](std::string path) {
    manager->DownloadUrl(content::DownloadRequestUtils::CreateDownloadForWebContentsMainFrame(
        window_->contents("work"), server.GetURL(path), TRAFFIC_ANNOTATION_FOR_TESTS));
  };
  start("/transfer.txt");
  stream.WaitForRequest();
  stream.Send("HTTP/1.1 200 OK\r\nContent-Type: text/plain\r\nContent-Disposition: attachment; filename=transfer.txt\r\nContent-Length: 262144\r\n\r\n");
  stream.Send(std::string(32768, 'x'));
  download::DownloadItem* item = nullptr;
  ASSERT_TRUE(base::test::RunUntil([&] {
    content::DownloadManager::DownloadVector items;
    manager->GetAllDownloads(&items);
    if (items.size() != 1) return false;
    item = items[0];
    return item->GetReceivedBytes() > 0 && !item->GetTargetFilePath().empty();
  }));
  const auto guid = item->GetGuid();
  ASSERT_TRUE(base::test::RunUntil([&] { return FindButton(panel->widget()->GetContentsView(), u"Wstrzymaj"); }));
  ClickControl(FindButton(panel->widget()->GetContentsView(), u"Wstrzymaj"));
  ASSERT_TRUE(base::test::RunUntil([&] { return item->IsPaused(); }));
  EXPECT_FALSE(panel->Act(guid, DownloadPanel::Action::kReveal));
  ASSERT_TRUE(window_->Select("personal"));
  window_->ShowDownloads();
  EXPECT_TRUE(panel->visible_guids().empty());
  EXPECT_FALSE(panel->Act(guid, DownloadPanel::Action::kCancel));
  EXPECT_EQ(download::DownloadItem::IN_PROGRESS, item->GetState());
  EXPECT_TRUE(item->IsPaused());
  ASSERT_TRUE(window_->Select("work"));
  window_->ShowDownloads();
  ASSERT_TRUE(base::test::RunUntil([&] { return FindButton(panel->widget()->GetContentsView(), u"Wznów"); }));
  ClickControl(FindButton(panel->widget()->GetContentsView(), u"Wznów"));
  ASSERT_TRUE(base::test::RunUntil([&] { return !item->IsPaused(); }));
  stream.Send(std::string(262144 - 32768, 'x')); stream.Done();
  ASSERT_TRUE(base::test::RunUntil([&] { return item->GetState() == download::DownloadItem::COMPLETE; }));
  // A transfer seen in progress announces its end with a toast (design: Downloads).
  ASSERT_TRUE(base::test::RunUntil([&] { return base::StartsWith(window_->shell()->toast_text_for_testing(), u"Pobrano "); }));
  {
    base::ScopedAllowBlockingForTesting allow;
    std::string bytes;
    ASSERT_TRUE(base::ReadFileToString(item->GetTargetFilePath(), &bytes));
    EXPECT_EQ(std::string(262144, 'x'), bytes);
  }
  // Check Finder dispatch without opening a real OS window during automation.
  class RevealDelegate final : public content::DownloadManagerDelegate {
   public:
    void ShowDownloadInShell(download::DownloadItem* item) override { revealed = item; }
    void OpenDownload(download::DownloadItem* item) override { opened = item; }
    raw_ptr<download::DownloadItem> revealed = nullptr;
    raw_ptr<download::DownloadItem> opened = nullptr;
  } reveal;
  auto* original_delegate = manager->GetDelegate();
  manager->SetDelegate(&reveal);
  EXPECT_TRUE(panel->Act(guid, DownloadPanel::Action::kReveal));
  EXPECT_EQ(item, reveal.revealed);
  manager->SetDelegate(original_delegate);
  ASSERT_TRUE(base::test::RunUntil([&] {
    return panel->visible_guids().size() == 1 && panel->list_for_testing()->children().size() == 2;
  }));
  panel->widget()->LayoutRootViewIfNecessary();
  auto* root = panel->widget()->GetRootView();
  auto* download_row = panel->list_for_testing()->children()[1].get();
  const auto point = views::View::ConvertRectToTarget(
      download_row, root, download_row->GetLocalBounds()).CenterPoint();
  auto click = [&](int flags) {
    ui::MouseEvent press(ui::EventType::kMousePressed, point, point, base::TimeTicks::Now(),
                         ui::EF_LEFT_MOUSE_BUTTON | flags, ui::EF_LEFT_MOUSE_BUTTON);
    EXPECT_TRUE(root->OnMousePressed(press));
    ui::MouseEvent release(ui::EventType::kMouseReleased, point, point, base::TimeTicks::Now(),
                           ui::EF_LEFT_MOUSE_BUTTON, ui::EF_LEFT_MOUSE_BUTTON);
    root->OnMouseReleased(release);
  };
  manager->SetDelegate(&reveal);
  click(0);
  EXPECT_FALSE(reveal.opened);
  click(ui::EF_IS_DOUBLE_CLICK);
  EXPECT_EQ(item, reveal.opened);
  manager->SetDelegate(original_delegate);
  start("/cancel.txt"); cancelled.WaitForRequest();
  cancelled.Send("HTTP/1.1 200 OK\r\nContent-Type: text/plain\r\nContent-Disposition: attachment; filename=cancel.txt\r\nContent-Length: 262144\r\n\r\n");
  cancelled.Send(std::string(32768, 'y'));
  download::DownloadItem* second = nullptr;
  ASSERT_TRUE(base::test::RunUntil([&] {
    content::DownloadManager::DownloadVector items; manager->GetAllDownloads(&items);
    for (auto candidate : items) if (candidate->GetGuid() != guid) second = candidate;
    return second && second->GetReceivedBytes() > 0;
  }));
  ASSERT_TRUE(base::test::RunUntil([&] { return FindButton(panel->widget()->GetContentsView(), u"Anuluj"); }));
  ClickControl(FindButton(panel->widget()->GetContentsView(), u"Anuluj"));
  ASSERT_TRUE(base::test::RunUntil([&] { return second->GetState() == download::DownloadItem::CANCELLED; }));
  EXPECT_FALSE(panel->Act(second->GetGuid(), DownloadPanel::Action::kPauseResume));
  EXPECT_FALSE(panel->Act(second->GetGuid(), DownloadPanel::Action::kReveal));
  cancelled.Done();
  panel->widget()->Close();
  ASSERT_TRUE(base::test::RunUntil([&] { return !panel->widget(); }));
  window_->ShowDownloads();
  EXPECT_EQ(2u, panel->visible_guids().size());
}

// Design: Downloads — the footer's leading icon turns into a ring while files
// arrive and opens the list above it; with the sidebar slid away the start
// lands in a pill instead.
IN_PROC_BROWSER_TEST_F(ZitterProfilesBrowserTest, DownloadsRingAndStartCueFollowTheSidebar) {
  base::ScopedAllowBlockingForTesting test_files;
  base::test::ScopedRunLoopTimeout timeout(FROM_HERE, base::Seconds(30));
  NavigateBoth();ASSERT_TRUE(window_->Select("work"));
  base::ScopedTempDir directory;ASSERT_TRUE(directory.CreateUniqueTempDir());
  DownloadPrefs::FromBrowserContext(work_)->SetDownloadPath(directory.GetPath());work_->GetPrefs()->SetBoolean(prefs::kPromptForDownload, false);
  auto* shell=window_->shell();ASSERT_TRUE(base::test::RunUntil([&]{return shell->appearance_ready();}));
  auto* manager=work_->GetDownloadManager();ASSERT_TRUE(base::test::RunUntil([&]{return manager->IsManagerInitialized();}));
  net::EmbeddedTestServer server;net::test_server::ControllableHttpResponse first(&server,"/ring.bin"),second(&server,"/pill.bin");ASSERT_TRUE(server.Start());
  auto start=[&](std::string path){manager->DownloadUrl(content::DownloadRequestUtils::CreateDownloadForWebContentsMainFrame(window_->contents("work"),server.GetURL(path),TRAFFIC_ANNOTATION_FOR_TESTS));};
  auto* ring=shell->footer_action_for_testing(1);ASSERT_TRUE(ring);EXPECT_TRUE(ring->GetVisible());EXPECT_EQ(u"Pobrane",ring->GetTooltipText());
  // Docked sidebar: the arrow lands on the ring, which stays while bytes arrive.
  shell->SetPinned(true);shell->ShowSidebar();shell->sidebar_widget()->LayoutRootViewIfNecessary();
  start("/ring.bin");first.WaitForRequest();
  first.Send("HTTP/1.1 200 OK\r\nContent-Type: application/octet-stream\r\nContent-Disposition: attachment; filename=ring.bin\r\nContent-Length: 8192\r\n\r\n");first.Send(std::string(4096,'x'));
  ASSERT_TRUE(base::test::RunUntil([&]{return ring->GetTooltipText().find(u"ring.bin")!=std::u16string::npos;}));
  ASSERT_TRUE(base::test::RunUntil([&]{return !shell->download_cue_widget_for_testing()->IsVisible();}));
  EXPECT_FALSE(shell->download_cue_is_pill_for_testing());
  shell->sidebar_widget()->LayoutRootViewIfNecessary();
  const auto add=shell->footer_action_for_testing(0)->GetBoundsInScreen(),bounds=ring->GetBoundsInScreen();
  const auto footer=ring->parent()->GetBoundsInScreen();
  EXPECT_EQ(bounds.size(),gfx::Size(28,28));EXPECT_EQ(bounds.x(),footer.x());EXPECT_EQ(add.right(),footer.right());EXPECT_EQ(bounds.y(),add.y());
  // A click on the ring opens the list above it.
  {const auto point=ring->GetLocalBounds().CenterPoint();ui::MouseEvent press(ui::EventType::kMousePressed,point,point,base::TimeTicks::Now(),ui::EF_LEFT_MOUSE_BUTTON,ui::EF_LEFT_MOUSE_BUTTON);ui::MouseEvent release(ui::EventType::kMouseReleased,point,point,base::TimeTicks::Now(),ui::EF_LEFT_MOUSE_BUTTON,ui::EF_LEFT_MOUSE_BUTTON);
   ASSERT_TRUE(ring->OnMousePressed(press));ring->OnMouseReleased(release);}
  ASSERT_TRUE(base::test::RunUntil([&]{return window_->downloads()->widget()&&window_->downloads()->widget()->IsVisible();}));auto* panel=window_->downloads();ASSERT_TRUE(panel&&panel->widget()&&panel->widget()->IsVisible());
  const auto list=panel->widget()->GetWindowBoundsInScreen();const auto area=display::Screen::Get()->GetDisplayNearestWindow(window_->widget()->GetNativeWindow()).work_area();
  if(area.Contains(gfx::Rect(bounds.x()-16,bounds.y()-8-list.height(),list.width(),list.height()))){EXPECT_EQ(list.bottom(),bounds.y()-8);EXPECT_EQ(list.x(),bounds.x()-16);}
  panel->widget()->CloseNow();
  first.Send(std::string(4096,'x'));first.Done();
  // Finished: ✓ for a moment, then the icon rests.
  ASSERT_TRUE(base::test::RunUntil([&]{return ring->GetTooltipText()==u"Pobrane: gotowe";}));
  ASSERT_TRUE(base::test::RunUntil([&]{return ring->GetTooltipText()==u"Pobrane";}));
  // Sidebar slid away: the start lands in the page's lower left corner as a pill.
  shell->SetPinned(false);shell->sidebar_widget()->Hide();ASSERT_FALSE(shell->sidebar_visible());
  start("/pill.bin");second.WaitForRequest();
  second.Send("HTTP/1.1 200 OK\r\nContent-Type: application/octet-stream\r\nContent-Disposition: attachment; filename=pill.bin\r\nContent-Length: 2048\r\n\r\n");second.Send(std::string(1024,'x'));
  ASSERT_TRUE(base::test::RunUntil([&]{return shell->download_cue_is_pill_for_testing();}));
  const auto page=window_->widget()->GetClientAreaBoundsInScreen();const auto pill=shell->download_cue_widget_for_testing()->GetWindowBoundsInScreen();
  EXPECT_EQ(pill.x(),page.x()+16);EXPECT_EQ(pill.bottom(),page.bottom()-16);EXPECT_EQ(pill.height(),40);
  EXPECT_EQ(shell->downloads_anchor_in_screen(),pill);
  second.Send(std::string(1024,'x'));second.Done();
  ASSERT_TRUE(base::test::RunUntil([&]{return ring->GetTooltipText()==u"Pobrane";}));
}
// Design: Okno Pobrane — search, state and type filters, choosing files,
// removing them from the list with an undo toast, deleting one from the disk
// after a warning, and clearing finished files.
IN_PROC_BROWSER_TEST_F(ZitterProfilesBrowserTest, DownloadsWindowFiltersRemoveUndoDeleteAndClear) {
  base::ScopedAllowBlockingForTesting test_files;
  base::test::ScopedRunLoopTimeout timeout(FROM_HERE, base::Seconds(30));
  NavigateBoth();ASSERT_TRUE(window_->Select("work"));
  base::ScopedTempDir directory;ASSERT_TRUE(directory.CreateUniqueTempDir());
  DownloadPrefs::FromBrowserContext(work_)->SetDownloadPath(directory.GetPath());work_->GetPrefs()->SetBoolean(prefs::kPromptForDownload,false);
  auto* manager=work_->GetDownloadManager();ASSERT_TRUE(base::test::RunUntil([&]{return manager->IsManagerInitialized();}));
  net::EmbeddedTestServer server;net::test_server::ControllableHttpResponse pdf(&server,"/faktura-2026-10.pdf"),zip(&server,"/zdjecia-wesele.zip");ASSERT_TRUE(server.Start());
  auto fetch=[&](net::test_server::ControllableHttpResponse& response,std::string path){
    manager->DownloadUrl(content::DownloadRequestUtils::CreateDownloadForWebContentsMainFrame(window_->contents("work"),server.GetURL(path),TRAFFIC_ANNOTATION_FOR_TESTS));
    response.WaitForRequest();response.Send("HTTP/1.1 200 OK\r\nContent-Type: application/octet-stream\r\nContent-Disposition: attachment\r\nContent-Length: 16\r\n\r\n"+std::string(16,'x'));response.Done();};
  fetch(pdf,"/faktura-2026-10.pdf");fetch(zip,"/zdjecia-wesele.zip");
  window_->ShowDownloads();auto* panel=window_->downloads();ASSERT_TRUE(panel&&panel->widget());
  auto finished=[&]{content::DownloadManager::DownloadVector items;manager->GetAllDownloads(&items);return items.size()==2&&std::ranges::all_of(items,[](const auto& item){return item->GetState()==download::DownloadItem::COMPLETE;});};
  ASSERT_TRUE(base::test::RunUntil(finished));
  std::string pdf_guid,zip_guid;base::FilePath pdf_path;
  {content::DownloadManager::DownloadVector items;manager->GetAllDownloads(&items);for(const auto& item:items){if(item->GetTargetFilePath().Extension()==FILE_PATH_LITERAL(".pdf")){pdf_guid=item->GetGuid();pdf_path=item->GetTargetFilePath();}else zip_guid=item->GetGuid();}}
  ASSERT_FALSE(pdf_guid.empty());ASSERT_FALSE(zip_guid.empty());ASSERT_TRUE(base::PathExists(pdf_path));
  using F=DownloadPanel::StateFilter;
  ASSERT_TRUE(base::test::RunUntil([&]{return panel->visible_guids().size()==2u;}));
  EXPECT_EQ(2,panel->count_for_testing(F::kAll));EXPECT_EQ(2,panel->count_for_testing(F::kDone));EXPECT_EQ(0,panel->count_for_testing(F::kActive));
  EXPECT_NE(std::u16string::npos,panel->folder_for_testing().find(directory.GetPath().BaseName().LossyDisplayName()));
  // Search: name words, case and diacritics aside.
  panel->search_for_testing()->SetText(u"FAKTURA");panel->SetQuery(u"FAKTURA");EXPECT_EQ(std::vector<std::string>{pdf_guid},panel->visible_guids());EXPECT_EQ(1,panel->count_for_testing(F::kDone));
  panel->SetQuery(u"");
  // Type: documents only; state: in progress shows nothing.
  panel->SetCategory(2);EXPECT_EQ(std::vector<std::string>{pdf_guid},panel->visible_guids());panel->SetCategory(0);
  panel->SetStateFilter(F::kActive);EXPECT_TRUE(panel->visible_guids().empty());panel->SetStateFilter(F::kAll);
  // Choose the archive and remove it from the list: the toast undoes it.
  panel->SetChoosing(true);panel->Choose(zip_guid,true);EXPECT_EQ(1u,panel->chosen().size());panel->RemoveChosen();
  EXPECT_FALSE(panel->choosing());EXPECT_EQ(std::vector<std::string>{pdf_guid},panel->visible_guids());
  auto* shell=window_->shell();EXPECT_NE(std::u16string::npos,shell->toast_text_for_testing().find(u"Usunięto z listy"));
  shell->UndoToast();ASSERT_TRUE(base::test::RunUntil([&]{return panel->visible_guids().size()==2u;}));
  // Deleting from the disk asks first; cancelling keeps the file.
  ASSERT_TRUE(panel->Act(pdf_guid,DownloadPanel::Action::kDelete));
  ASSERT_TRUE(base::test::RunUntil([&]{return shell->danger_dialog_for_testing()&&shell->danger_dialog_for_testing()->IsVisible();}));
  shell->danger_dialog_for_testing()->widget_delegate()->AsDialogDelegate()->CancelDialog();
  ASSERT_TRUE(base::test::RunUntil([&]{return !shell->danger_dialog_for_testing();}));EXPECT_TRUE(base::PathExists(pdf_path));
  ASSERT_TRUE(panel->Act(pdf_guid,DownloadPanel::Action::kDelete));
  ASSERT_TRUE(base::test::RunUntil([&]{return shell->danger_dialog_for_testing()&&shell->danger_dialog_for_testing()->IsVisible();}));
  shell->danger_dialog_for_testing()->widget_delegate()->AsDialogDelegate()->AcceptDialog();
  ASSERT_TRUE(base::test::RunUntil([&]{return !base::PathExists(pdf_path)&&panel->visible_guids()==std::vector<std::string>{zip_guid};}));
  // „Wyczyść”: finished files leave the list; the file itself stays.
  panel->ClearList(DownloadPanel::Clear::kDone);EXPECT_TRUE(panel->visible_guids().empty());
  ASSERT_TRUE(base::test::RunUntil([&]{content::DownloadManager::DownloadVector items;manager->GetAllDownloads(&items);return items.empty();}));
}

// A transfer cut off by the network resumes from „Wznów” where it stopped
// (a Range request), and its row says only „Przerwano” meanwhile.
IN_PROC_BROWSER_TEST_F(ZitterProfilesBrowserTest, DownloadsInterruptedResumesFromThePanel) {
  base::ScopedAllowBlockingForTesting test_files;
  base::test::ScopedRunLoopTimeout timeout(FROM_HERE, base::Seconds(30));
  NavigateBoth();ASSERT_TRUE(window_->Select("work"));
  base::ScopedTempDir directory;ASSERT_TRUE(directory.CreateUniqueTempDir());
  DownloadPrefs::FromBrowserContext(work_)->SetDownloadPath(directory.GetPath());work_->GetPrefs()->SetBoolean(prefs::kPromptForDownload,false);
  auto* manager=work_->GetDownloadManager();ASSERT_TRUE(base::test::RunUntil([&]{return manager->IsManagerInitialized();}));
  net::EmbeddedTestServer server;net::test_server::ControllableHttpResponse first(&server,"/resume.bin"),again(&server,"/resume.bin");ASSERT_TRUE(server.Start());
  manager->DownloadUrl(content::DownloadRequestUtils::CreateDownloadForWebContentsMainFrame(window_->contents("work"),server.GetURL("/resume.bin"),TRAFFIC_ANNOTATION_FOR_TESTS));
  first.WaitForRequest();
  first.Send("HTTP/1.1 200 OK\r\nContent-Type: application/octet-stream\r\nContent-Disposition: attachment\r\nContent-Length: 8192\r\nAccept-Ranges: bytes\r\nETag: \"v1\"\r\nLast-Modified: Tue, 03 Nov 2026 10:00:00 GMT\r\n\r\n"+std::string(4096,'a'));
  download::DownloadItem* item=nullptr;
  ASSERT_TRUE(base::test::RunUntil([&]{content::DownloadManager::DownloadVector items;manager->GetAllDownloads(&items);if(items.empty())return false;item=items[0];return item->GetReceivedBytes()>=4096&&!item->GetTargetFilePath().empty();}));
  static_cast<download::DownloadItemImpl*>(item)->SimulateErrorForTesting(download::DOWNLOAD_INTERRUPT_REASON_NETWORK_FAILED);
  ASSERT_TRUE(base::test::RunUntil([&]{return item->GetState()==download::DownloadItem::INTERRUPTED;}));ASSERT_TRUE(item->CanResume());
  window_->ShowDownloads();auto* panel=window_->downloads();ASSERT_TRUE(panel&&panel->widget());
  ASSERT_TRUE(base::test::RunUntil([&]{return FindButton(panel->widget()->GetContentsView(),u"Wznów");}));
  if(MetalPresents())ASSERT_TRUE(base::test::RunUntil([&]{return panel->scene_contains_text_for_testing("⚠ Przerwano");}));
  ClickControl(FindButton(panel->widget()->GetContentsView(),u"Wznów"));
  again.WaitForRequest();
  EXPECT_EQ("bytes=4096-",again.http_request()->headers.at("Range"));
  again.Send("HTTP/1.1 206 Partial Content\r\nContent-Type: application/octet-stream\r\nContent-Range: bytes 4096-8191/8192\r\nContent-Length: 4096\r\nAccept-Ranges: bytes\r\nETag: \"v1\"\r\nLast-Modified: Tue, 03 Nov 2026 10:00:00 GMT\r\n\r\n"+std::string(4096,'b'));again.Done();
  ASSERT_TRUE(base::test::RunUntil([&]{return item->GetState()==download::DownloadItem::COMPLETE;}));
  std::string body;ASSERT_TRUE(base::ReadFileToString(item->GetTargetFilePath(),&body));EXPECT_EQ(std::string(4096,'a')+std::string(4096,'b'),body);
}

