IN_PROC_BROWSER_TEST_F(ZitterProfilesBrowserTest, CommandCenterSearchAndDispatch) {
  auto* shell = window_->shell();
  const auto url = embedded_test_server()->GetURL("/storage_probe.html?command-center");
  ASSERT_TRUE(content::NavigateToURL(window_->contents("work"), url));
  window_->OpenCommandPalette();
  EXPECT_FALSE(shell->suggestions().empty());
  SetPaletteQuery(u"> skroty");  // Polish accents are optional.
  ASSERT_EQ(1u, shell->suggestions().size());
  EXPECT_EQ("shortcuts", shell->suggestions().front().command_id);
  ui::KeyEvent enter(ui::EventType::kKeyPressed, ui::VKEY_RETURN, 0);
  EXPECT_TRUE(shell->address_input()->view()->OnKeyPressed(enter));
  ASSERT_TRUE(base::test::RunUntil([&] { return shell->tools_widget() && shell->tools_widget()->IsVisible(); }));
  EXPECT_FALSE(shell->address_visible());
  shell->CloseOverlays();
  window_->OpenCommandPalette(); SetPaletteQuery(u"> zapisz snapshot");
  ASSERT_EQ(1u, shell->suggestions().size());
  const auto before = window_->timeline_marks_for_testing().size();
  EXPECT_TRUE(shell->address_input()->view()->OnKeyPressed(enter));
  ASSERT_TRUE(base::test::RunUntil([&] { return window_->timeline_marks_for_testing().size() > before; }));
  EXPECT_EQ("Command Center", window_->timeline_marks_for_testing().back());
  EXPECT_TRUE(shell->time_machine_visible());
  shell->CloseOverlays(); window_->OpenCommandPalette(); SetPaletteQuery(u"> no-such-command-xyz");
  EXPECT_TRUE(shell->suggestions().empty());
  EXPECT_TRUE(shell->address_input()->view()->OnKeyPressed(enter));
  EXPECT_TRUE(shell->address_visible());
  EXPECT_EQ(url, window_->contents("work")->GetVisibleURL());
  SetPaletteQuery(u"g ustawienia");
  ASSERT_FALSE(shell->suggestions().empty());
  EXPECT_TRUE(shell->suggestions().front().command_id.empty());
  EXPECT_EQ("www.google.com", shell->suggestions().front().url.host());
  shell->OpenAddress(false); SetPaletteQuery(u"skroty");
  for (const auto& item : shell->suggestions()) EXPECT_TRUE(item.command_id.empty());
  shell->CloseOverlays();
  auto stale = window_->CommandResults(u"> reload");
  std::erase_if(stale, [](const auto& result) { return result.command_id != "reload"; });
  ASSERT_EQ(1u, stale.size());
  ASSERT_TRUE(window_->NavigateFromBar(url, true));
  ASSERT_TRUE(content::WaitForLoadStop(window_->contents("work")));
  EXPECT_FALSE(window_->ExecuteCommand(stale.front()));
  window_->CloseTab(0);  // Replacement now has the same index and URL, but a different page identity.
  ASSERT_EQ(1u, window_->tab_count("work"));
  EXPECT_FALSE(window_->ExecuteCommand(stale.front()));
  const auto actions = window_->CommandResults(u">");
  auto settings = std::find_if(actions.begin(), actions.end(), [](const auto& item) { return item.command_id == "settings"; });
  ASSERT_NE(settings, actions.end());
  ASSERT_TRUE(window_->Select("personal"));
  EXPECT_FALSE(window_->ExecuteCommand(*settings));  // Queued action cannot cross workspaces.
}

// „Kopiuj adres strony” puts the address on the clipboard (the pill trembles,
// design: AddressPill); pages without a web address offer no copy.
IN_PROC_BROWSER_TEST_F(ZitterProfilesBrowserTest, AddressTabCompletesSelectionWithoutNavigating) {
  auto* shell = window_->shell();
  ASSERT_TRUE(base::test::RunUntil([&] { return shell->appearance_ready(); }));
  shell->OpenAddress(true);
  SetPaletteQuery(u"completion-target");
  PaletteResult result;
  result.title = u"Completion target";
  result.url = embedded_test_server()->GetURL("/storage_probe.html?completed");
  shell->SetSearchResults(u"completion-target", "work-profile", {result});
  const auto original = window_->contents("work")->GetLastCommittedURL();
  const auto count = window_->tab_count("work");
  ui::KeyEvent down(ui::EventType::kKeyPressed, ui::VKEY_DOWN, 0);
  for (size_t i = 0; i < shell->suggestions().size(); ++i) {
    if (shell->suggestions()[shell->palette_selection_for_testing()].url == result.url) break;
    ASSERT_TRUE(shell->HandleAddressKey(down));
  }
  ASSERT_EQ(result.url, shell->suggestions()[shell->palette_selection_for_testing()].url);
  ui::KeyEvent tab(ui::EventType::kKeyPressed, ui::VKEY_TAB, 0);
  shell->address_input()->RequestFocus();
  ASSERT_TRUE(base::test::RunUntil([&] { return shell->address_input()->HasFocus(); }));
  auto* focus = shell->address_input()->view()->GetFocusManager();
  EXPECT_TRUE(focus->OnKeyEvent(tab));
  EXPECT_EQ(shell->address_input()->view(), focus->GetFocusedView());
  ASSERT_TRUE(shell->address_input()->view()->OnKeyPressed(tab));
  EXPECT_EQ(base::UTF8ToUTF16(result.url.spec()), shell->address_input()->GetText());
  EXPECT_EQ(gfx::Range(shell->address_input()->GetText().size()), shell->address_input()->GetSelectedRange());
  EXPECT_TRUE(shell->address_visible());
  EXPECT_EQ(count, window_->tab_count("work"));
  EXPECT_EQ(original, window_->contents("work")->GetLastCommittedURL());
}

TEST(CleanUrlForCopyTest, MatchesBraveRulesAndPreservesFunctionalUrlParts) {
  EXPECT_EQ("https://www.youtube.com/watch?v=video&keep=a%2Bb&keep=#t=3",
            CleanUrlForCopy(GURL("https://www.youtube.com/watch?v=video&si=1"
                                "&keep=a%2Bb&si=2&keep=&utm_medium=mail#t=3")));
  EXPECT_FALSE(CleanUrlForCopy(GURL("https://www.youtube.com/playlist?si=1")));
  EXPECT_FALSE(CleanUrlForCopy(GURL("https://youtube.com.example.org/watch?si=1")));
  EXPECT_FALSE(CleanUrlForCopy(GURL("https://app.hive.co/?h_sid=1")));
  EXPECT_EQ("https://example.org/#section",
            CleanUrlForCopy(GURL("https://example.org/?h_sid=1#section")));
  EXPECT_FALSE(CleanUrlForCopy(
      GURL("https://example.org/?%58-Amz-Signature=signed&utm_source=mail")));
  EXPECT_FALSE(CleanUrlForCopy(GURL("file:///tmp/example?utm_source=mail")));
}

IN_PROC_BROWSER_TEST_F(ZitterProfilesBrowserTest, AddressClipboardUsesPlatformShortcuts) {
  auto previous = ui::Clipboard::TakeForCurrentThread();
  ui::TestClipboard::CreateForCurrentThread();
  base::ScopedClosureRunner restore(base::BindOnce([](std::unique_ptr<ui::Clipboard> old) {
    ui::Clipboard::DestroyClipboardForCurrentThread();
    if (old) ui::Clipboard::SetClipboardForCurrentThread(std::move(old));
  }, std::move(previous)));
  auto* shell = window_->shell();
  ASSERT_TRUE(base::test::RunUntil([&] { return shell->appearance_ready(); }));
  shell->OpenAddress(false);
  auto* field = shell->address_input();
  field->RequestFocus();
  constexpr char16_t full_url[] = u"https://example.com/clipboard?utm_source=test&id=a%2Bb#part";
  constexpr char16_t clean_url[] = u"https://example.com/clipboard?id=a%2Bb#part";
  SetPaletteQuery(full_url);
#if BUILDFLAG(IS_MAC)
  constexpr int primary = ui::EF_COMMAND_DOWN;
#else
  constexpr int primary = ui::EF_CONTROL_DOWN;
#endif
  auto key = [&](ui::KeyboardCode code) {
    ui::KeyEvent event(ui::EventType::kKeyPressed, code, primary);
    return field->view()->OnKeyPressed(event);
  };
  const auto copy = [&] {
    EXPECT_TRUE(key(ui::VKEY_C));
    base::test::TestFuture<std::u16string> copied;
    ui::Clipboard::GetForCurrentThread()->ReadText(ui::ClipboardBuffer::kCopyPaste, std::nullopt, copied.GetCallback());
    return copied.Get();
  };
  ASSERT_TRUE(key(ui::VKEY_A));
  EXPECT_EQ(clean_url, copy());
  EXPECT_EQ(full_url, field->GetText());
  field->SelectRange(gfx::Range(0, 19));
  EXPECT_EQ(u"https://example.com", copy());
  ASSERT_TRUE(key(ui::VKEY_A));
  ASSERT_TRUE(window_->WritePreference("clean_address_copies", 0));
  EXPECT_EQ(full_url, copy());
  ASSERT_TRUE(key(ui::VKEY_X));
  EXPECT_TRUE(field->GetText().empty());
  ASSERT_TRUE(key(ui::VKEY_V));
  ASSERT_TRUE(base::test::RunUntil([&] { return field->GetText() == full_url; }));
  EXPECT_TRUE(shell->address_visible());
#if !BUILDFLAG(IS_MAC)
  ui::KeyEvent altgr(ui::EventType::kKeyPressed, ui::VKEY_A, ui::EF_CONTROL_DOWN | ui::EF_ALT_DOWN);
  EXPECT_FALSE(field->view()->OnKeyPressed(altgr));
  EXPECT_EQ(full_url, field->GetText());
  field->input_client()->InsertChar(ui::KeyEvent::FromCharacter(u'ą', ui::VKEY_A, ui::DomCode::US_A, ui::EF_CONTROL_DOWN | ui::EF_ALT_DOWN));
  EXPECT_EQ(std::u16string(full_url) + u"ą", field->GetText());
#endif
}

