IN_PROC_BROWSER_TEST_F(ZitterProfilesBrowserTest, SidebarPairRustNodeOwnsMembersAnchorAndFolderVisibility) {
  auto* shell = window_->shell();
  ASSERT_TRUE(base::test::RunUntil([&] { return shell->appearance_ready(); }));
  if (!shell->workspace_input()->rust_editor()) return;
  shell->SetWorkspaceAnimations(false);
  base::FilePath source;
  ASSERT_TRUE(base::PathService::Get(base::DIR_SRC_TEST_DATA_ROOT, &source));
  window_->PreviewArcImport(source.AppendASCII("zitter/testdata/arc"));
  ASSERT_TRUE(base::test::RunUntil([&] { return window_->import_ready(); }));
  ASSERT_TRUE(window_->ApplyArcImport());
  ASSERT_TRUE(base::test::RunUntil([&] { return !window_->profiles_busy(); }));
  ASSERT_TRUE(window_->Select("arc-space-space-a"));
  shell->CloseOverlays(true); shell->SetPinned(true); shell->ShowSidebar();
  window_->OpenPinnedItem("tab-a"); window_->OpenPinnedItem("tab-b");
  ASSERT_EQ(3u, window_->tab_count("arc-space-space-a"));
  EXPECT_EQ(0u, shell->sidebar_pair_for_testing()[0]);
  const auto root = shell->scene_parent_id_for_testing(shell->tab_button(0));
  ASSERT_TRUE(window_->SplitTab(1));
  shell->sidebar_widget()->LayoutRootViewIfNecessary();
  auto pair = shell->sidebar_pair_for_testing();
  ASSERT_NE(0u, pair[0]); EXPECT_EQ(1u, pair[2]);
  EXPECT_NE(root, pair[1]);  // Anchored inside the pinned page's folder group.
  EXPECT_EQ(pair[0], shell->scene_parent_id_for_testing(shell->tab_button(1)));
  EXPECT_EQ(pair[0], shell->scene_parent_id_for_testing(shell->tab_button(2)));
  EXPECT_EQ(root, shell->scene_parent_id_for_testing(shell->tab_button(0)));
  const auto first = shell->sidebar_node_id_for_testing(shell->tab_button(1));
  auto* nested = SidebarNamedButton(shell->sidebar_view(), u"▾ Projekt");
  ASSERT_TRUE(nested); ActivateSidebarRow(nested);
  shell->sidebar_widget()->LayoutRootViewIfNecessary();
  EXPECT_EQ(0u, shell->sidebar_pair_for_testing()[2]);
  EXPECT_FALSE(shell->tab_button(2)->IsDrawn());
  ActivateSidebarRow(SidebarNamedButton(shell->sidebar_view(), u"▸ Projekt"));
  shell->sidebar_widget()->LayoutRootViewIfNecessary();
  EXPECT_EQ(1u, shell->sidebar_pair_for_testing()[2]);
  EXPECT_TRUE(shell->tab_button(2)->IsDrawn());
  window_->Unsplit(1);
  shell->sidebar_widget()->LayoutRootViewIfNecessary();
  EXPECT_EQ(0u, shell->sidebar_pair_for_testing()[0]);
  if (auto* row = shell->tab_button(1)) {
    EXPECT_EQ(root, shell->scene_parent_id_for_testing(row));
    EXPECT_EQ(first, shell->sidebar_node_id_for_testing(row));
  }
}
// A tab dragged with the real pointer onto a shown split joins it on the first
// drop, at the edge it was dropped on, including the page's left half.
IN_PROC_BROWSER_TEST_F(ZitterProfilesBrowserTest, NativeDragJoinsShownSplitFirstTime) {
  auto* shell = window_->shell();
  ASSERT_TRUE(base::test::RunUntil([&] { return shell->appearance_ready(); }));
  shell->SetWorkspaceAnimations(false);
  const auto url = embedded_test_server()->GetURL("/storage_probe.html");
  ASSERT_TRUE(window_->NavigateFromBar(url, true));
  window_->SelectTab(0); ASSERT_TRUE(window_->SplitTab(1));
  ASSERT_TRUE(window_->NavigateFromBar(embedded_test_server()->GetURL("/storage_probe.html?third"), true));
  const size_t third = window_->tab_count("work") - 1;
  window_->SelectTab(0);
  shell->CloseOverlays(true); shell->SetPinned(true); shell->ShowSidebar();
  shell->sidebar_widget()->LayoutRootViewIfNecessary(); window_->widget()->LayoutRootViewIfNecessary();
  if(MetalPresents())ASSERT_TRUE(base::test::RunUntil([&] { return shell->metal_sidebar_visible(); }));
  ASSERT_EQ(2u, shell->split_tabs_for_testing().size());
  EnableNativeUIControls();
  ASSERT_TRUE(ui_test_utils::ShowAndFocusNativeWindow(window_->widget()->GetNativeWindow()));
  const auto sidebar_window = shell->sidebar_widget()->GetNativeWindow();
  auto move = [&](gfx::Point p) {
    base::test::TestFuture<void> done;
    return ui_controls::SendMouseMoveNotifyWhenDone(p.x(), p.y(), done.GetCallback(), sidebar_window) && done.Wait();
  };
  auto mouse = [&](int state) {
    base::test::TestFuture<void> done;
    return ui_controls::SendMouseEventsNotifyWhenDone(ui_controls::LEFT, state, done.GetCallback(), ui_controls::kNoAccelerator, sidebar_window) && done.Wait();
  };
  ASSERT_TRUE(shell->tab_button(third));
  ASSERT_TRUE(move(shell->tab_button(third)->GetBoundsInScreen().CenterPoint()));
  ASSERT_TRUE(mouse(ui_controls::DOWN));
  const auto content = shell->content_host()->GetBoundsInScreen();
  // The left part of the page, not only its right half, takes the drop.
  ASSERT_TRUE(move(gfx::Point(content.x() + content.width() / 4, content.CenterPoint().y())));
  ASSERT_TRUE(move(gfx::Point(content.x() + content.width() / 8, content.CenterPoint().y())));
  EXPECT_EQ(std::optional<size_t>(0), shell->split_drop_slot_for_testing());
  ASSERT_TRUE(mouse(ui_controls::UP));
  ASSERT_TRUE(base::test::RunUntil([&] { return shell->split_tabs_for_testing().size() == 3u; }));
  EXPECT_EQ(third, shell->split_tabs_for_testing()[0]);
}
