// The menu's pin is a real control: pinning puts the action in the header of
// this profile only, and the pinned pin unpins it again.
IN_PROC_BROWSER_TEST_F(ZitterProfilesBrowserTest, ExtensionMenuPinsAndUnpinsPerProfile) {
  base::ScopedTempDir dir;
  {
    base::ScopedAllowBlockingForTesting allow;
    ASSERT_TRUE(dir.CreateUniqueTempDir());
  }
  const auto extension = LoadTestExtension(work_, WriteTestExtension(dir.GetPath(), "Pinboard", SK_ColorBLUE, false));
  ASSERT_TRUE(extension);
  PinAction(work_, extension->id(), false);
  auto* bar = window_->extensions_bar();
  NavigateBoth();
  ASSERT_TRUE(window_->Select("work"));
  ASSERT_TRUE(base::test::RunUntil([&] { return bar->profile() == work_.get(); }));
  EXPECT_TRUE(ShownActions(bar).empty());
  auto click = [](views::Button* button) {
    ui::MouseEvent event(ui::EventType::kMousePressed, gfx::Point(), gfx::Point(), base::TimeTicks::Now(),
                         ui::EF_LEFT_MOUSE_BUTTON, ui::EF_LEFT_MOUSE_BUTTON);
    views::test::ButtonTestApi(button).NotifyClick(event);
  };
  bar->ToggleMenu();
  ASSERT_TRUE(bar->menu_for_testing());
  auto* menu = bar->menu_for_testing()->GetRootView();
  // An unpinned pin shows on hover; the row is hovered when the pointer is on it.
  views::Button* pin = nullptr;
  ASSERT_TRUE(base::test::RunUntil([&] {
    pin = FindRowButton(menu, u"Pinboard", u"Przypnij");
    if (!pin) {
      // Reveal it as hovering would.
      std::function<void(views::View*)> reveal = [&](views::View* view) {
        if (view->GetViewAccessibility().GetCachedName() == u"Przypnij") view->SetVisible(true);
        for (const auto& child : view->children()) reveal(child.get());
      };
      reveal(menu);
      pin = FindRowButton(menu, u"Pinboard", u"Przypnij");
    }
    return pin != nullptr;
  }));
  click(pin);
  ASSERT_TRUE(base::test::RunUntil([&] { return ShownActions(bar) == std::vector<std::string>{extension->id()}; }));
  EXPECT_TRUE(ToolbarActionsModel::Get(work_)->IsActionPinned(extension->id()));
  // The menu rebuilds after the click; its pin is now "Odepnij" and stays shown.
  views::Button* unpin = nullptr;
  ASSERT_TRUE(base::test::RunUntil([&] {
    unpin = bar->menu_for_testing() ? FindRowButton(bar->menu_for_testing()->GetRootView(), u"Pinboard", u"Odepnij") : nullptr;
    return unpin != nullptr;
  }));
  click(unpin);
  ASSERT_TRUE(base::test::RunUntil([&] { return ShownActions(bar).empty(); }));
  EXPECT_FALSE(ToolbarActionsModel::Get(work_)->IsActionPinned(extension->id()));
  bar->CloseMenus();
  ASSERT_TRUE(base::test::RunUntil([&] { return !bar->menu_for_testing(); }));
  EXPECT_FALSE(ToolbarActionsModel::Get(personal_)->HasAction(extension->id()));
}

// Installing a packed extension with its confirmation (the Web Store path):
// the prompt opens over the Zitter window, the extension lands only in the
// profile of the page that asked, no stock Chrome window opens afterwards and
// the puzzle trembles.
IN_PROC_BROWSER_TEST_F(ZitterProfilesBrowserTest, ExtensionInstallPromptsOverZitterAndStaysInItsProfile) {
  base::ScopedTempDir dir;
  base::FilePath crx;
  {
    base::ScopedAllowBlockingForTesting allow;
    ASSERT_TRUE(dir.CreateUniqueTempDir());
    const auto source = WriteTestExtension(dir.GetPath(), "Packed", SK_ColorGREEN, false);
    crx = dir.GetPath().AppendASCII("packed.crx");
    extensions::ExtensionCreator creator;
    ASSERT_TRUE(creator.Run(source, crx, base::FilePath(), dir.GetPath().AppendASCII("packed.pem"),
                            extensions::ExtensionCreator::kOverwriteCRX)) << creator.error_message();
  }
  auto* bar = window_->extensions_bar();
  NavigateBoth();
  ASSERT_TRUE(window_->Select("work"));
  ASSERT_TRUE(base::test::RunUntil([&] { return bar->profile() == work_.get(); }));
  const size_t browsers = GlobalBrowserCollection::GetInstance()->GetSize();
  ExtensionInstallDialogView::SetInstallButtonDelayForTesting(0);
  views::NamedWidgetShownWaiter prompt_shown(views::test::AnyWidgetTestPasskey{}, "ExtensionInstallDialogView");
  extensions::TestExtensionRegistryObserver installed(extensions::ExtensionRegistry::Get(work_));
  auto installer = extensions::CrxInstaller::Create(
      work_, std::make_unique<ExtensionInstallPrompt>(window_->contents("work"),
                 std::make_unique<extensions::InstallPromptData>(extensions::InstallPromptData::UNSET_PROMPT_TYPE)));
  // Web Store installs carry an approval; a local .crx needs this instead.
  installer->set_off_store_install_allow_reason(extensions::CrxInstaller::OffStoreInstallAllowedInTest);
  installer->InstallCrx(crx);
  auto* prompt = prompt_shown.WaitIfNeededAndGet();
  ASSERT_TRUE(prompt);
  // Modal to Zitter's window, not to a stock browser.
  EXPECT_EQ(window_->widget(), prompt->parent());
  prompt->widget_delegate()->AsDialogDelegate()->AcceptDialog();
  const auto extension = installed.WaitForExtensionInstalled();
  ASSERT_TRUE(extension);
  EXPECT_FALSE(extensions::ExtensionRegistry::Get(personal_)->GetInstalledExtension(extension->id()));
  ASSERT_TRUE(base::test::RunUntil([&] { return bar->tremor_for_testing(); }));
  ASSERT_TRUE(base::test::RunUntil([&] { return Shown(bar, extension->id()).has_value(); }));
  base::RunLoop().RunUntilIdle();
  EXPECT_EQ(browsers, GlobalBrowserCollection::GetInstance()->GetSize());
}


// The tabs API sees Zitter tabs: tabs.query/get from the service worker and the
// popup, tabs.sendMessage to the content script, scripting.executeScript and a
// per-tab badge, all within the extension's own profile.
IN_PROC_BROWSER_TEST_F(ZitterProfilesBrowserTest, ExtensionTabsApiSeesZitterTabsOfItsProfile) {
  base::ScopedTempDir dir;
  {
    base::ScopedAllowBlockingForTesting allow;
    ASSERT_TRUE(dir.CreateUniqueTempDir());
  }
  const auto extension = LoadTestExtension(work_, WriteTestExtension(dir.GetPath(), "Keeper", SK_ColorBLUE, true));
  ASSERT_TRUE(extension);
  auto* bar = window_->extensions_bar();
  NavigateBoth();
  ASSERT_TRUE(window_->Select("work"));
  ASSERT_TRUE(base::test::RunUntil([&] { return Shown(bar, extension->id()).has_value(); }));
  auto* page = window_->contents("work");
  auto badge = [&] { return Shown(bar, extension->id())->badge; };
  auto run = [&](std::string script) {
    ASSERT_TRUE(extensions::BackgroundScriptExecutor::ExecuteScriptAsync(work_, extension->id(), script));
  };
  // The active tab of the current window is the page on screen.
  run("chrome.tabs.query({active: true, currentWindow: true}).then(tabs => chrome.action.setBadgeText({text: "
      "tabs.length === 1 && tabs[0].url.includes('storage_probe') ? 'q1' : 'q' + tabs.length}));");
  ASSERT_TRUE(base::test::RunUntil([&] { return badge() == "q1"; })) << badge();
  // Only this profile's tabs: the personal page never shows up.
  run(base::StringPrintf("chrome.tabs.query({}).then(tabs => chrome.action.setBadgeText({text: "
      "tabs.length === %zu ? 'all' : 'n' + tabs.length}));", window_->tab_count("work")));
  ASSERT_TRUE(base::test::RunUntil([&] { return badge() == "all"; })) << badge();
  // A message to the content script, and its reply.
  run("chrome.tabs.query({active: true, currentWindow: true}).then(([tab]) => chrome.tabs.sendMessage(tab.id, 'ping'))"
      ".then(reply => chrome.action.setBadgeText({text: reply === 'here' ? 'msg' : 'nomsg'}));");
  ASSERT_TRUE(base::test::RunUntil([&] { return badge() == "msg"; })) << badge();
  // A script injected by tab id.
  run("chrome.tabs.query({active: true, currentWindow: true}).then(([tab]) => chrome.scripting.executeScript("
      "{target: {tabId: tab.id}, func: () => { document.title = 'from-extension'; }}));");
  ASSERT_TRUE(base::test::RunUntil([&] { return page->GetTitle() == u"from-extension"; }));
  // tabs.get and a badge set for that tab only.
  run("chrome.action.setBadgeText({text: ''}); chrome.tabs.query({active: true, currentWindow: true})"
      ".then(([tab]) => chrome.tabs.get(tab.id)).then(tab => chrome.action.setBadgeText({tabId: tab.id, text: 'tab'}));");
  ASSERT_TRUE(base::test::RunUntil([&] { return badge() == "tab"; })) << badge();
  // The popup asks for the current tab, as password managers do.
  bar->RunAction(extension->id());
  ASSERT_TRUE(base::test::RunUntil([&] { return bar->popup_for_testing() && bar->popup_for_testing()->IsVisible(); }));
  EXPECT_EQ(page->GetLastCommittedURL().spec(),
            content::EvalJs(bar->popup_contents_for_testing(),
                            "chrome.tabs.query({active: true, currentWindow: true}).then(tabs => tabs[0].url)"));
  // The personal space's page is invisible to this profile's extension.
  const int personal_tab = sessions::SessionTabHelper::IdForTab(window_->contents("personal")).id();
  EXPECT_EQ("missing", content::EvalJs(bar->popup_contents_for_testing(),
      base::StringPrintf("chrome.tabs.get(%d).then(() => 'found', () => 'missing')", personal_tab)));
}


// chrome.tabs events reach the extension for Zitter tabs of its profile: a load
// that completes, a new tab shown, a closed tab. Password managers repaint
// their icon on these.
IN_PROC_BROWSER_TEST_F(ZitterProfilesBrowserTest, ExtensionTabEventsFollowZitterTabs) {
  base::ScopedTempDir dir;
  {
    base::ScopedAllowBlockingForTesting allow;
    ASSERT_TRUE(dir.CreateUniqueTempDir());
  }
  const auto extension = LoadTestExtension(work_, WriteTestExtension(dir.GetPath(), "Watcher", SK_ColorBLUE, false,
      "chrome.tabs.onUpdated.addListener((id, info, tab) => {"
      "  if (info.status === 'complete' && tab.url && tab.url.includes('updated=1')) chrome.action.setBadgeText({text: 'upd'}); });"
      // The tab shown after a close is activated too; a removal stays on the badge.
      "let removed = false;"
      "chrome.tabs.onActivated.addListener(() => { if (!removed) chrome.action.setBadgeText({text: 'act'}); });"
      "chrome.tabs.onRemoved.addListener(() => { removed = true; chrome.action.setBadgeText({text: 'rem'}); });"));
  ASSERT_TRUE(extension);
  auto* bar = window_->extensions_bar();
  NavigateBoth();
  ASSERT_TRUE(window_->Select("work"));
  ASSERT_TRUE(base::test::RunUntil([&] { return Shown(bar, extension->id()).has_value(); }));
  auto badge = [&] { return Shown(bar, extension->id())->badge; };
  // A load in the other profile never reaches this profile's extension.
  ASSERT_TRUE(content::NavigateToURL(window_->contents("personal"), embedded_test_server()->GetURL("/storage_probe.html?updated=1")));
  ASSERT_TRUE(content::NavigateToURL(window_->contents("work"), embedded_test_server()->GetURL("/storage_probe.html?updated=1")));
  ASSERT_TRUE(base::test::RunUntil([&] { return badge() == "upd"; })) << badge();
  // A new tab shown in the space.
  ASSERT_TRUE(window_->NavigateFromBar(embedded_test_server()->GetURL("/storage_probe.html?second"), true));
  ASSERT_TRUE(base::test::RunUntil([&] { return badge() == "act"; })) << badge();
  // And closed again.
  window_->CloseActiveTab();
  ASSERT_TRUE(base::test::RunUntil([&] { return badge() == "rem"; })) << badge();
}


// chrome.windows sees each profile's Zitter tabs as one normal window, and the
// tabs API creates, activates, moves and closes Zitter tabs in it. Closing the
// window itself is refused: it holds every profile's spaces.
IN_PROC_BROWSER_TEST_F(ZitterProfilesBrowserTest, ExtensionWindowsAndTabOperationsUseZitter) {
  base::ScopedTempDir dir;
  {
    base::ScopedAllowBlockingForTesting allow;
    ASSERT_TRUE(dir.CreateUniqueTempDir());
  }
  const auto extension = LoadTestExtension(work_, WriteTestExtension(dir.GetPath(), "Organizer", SK_ColorBLUE, false));
  ASSERT_TRUE(extension);
  auto* bar = window_->extensions_bar();
  NavigateBoth();
  ASSERT_TRUE(window_->Select("work"));
  ASSERT_TRUE(base::test::RunUntil([&] { return Shown(bar, extension->id()).has_value(); }));
  const size_t tabs = window_->tab_count("work");
  const GURL shown = window_->contents("work")->GetLastCommittedURL();
  const std::string script = base::StringPrintf(R"(let step = ''; (async () => {
    const fail = text => chrome.action.setBadgeText({text});
    step = 'g'; const win = await chrome.windows.getCurrent({populate: true});
    if (win.type !== 'normal' || win.tabs.length !== %zu) return fail('w' + win.tabs.length);
    step = 'l'; const all = await chrome.windows.getAll();
    if (all.length !== 1 || all[0].id !== win.id) return fail('a' + all.length);
    step = 'q'; const [active] = await chrome.tabs.query({active: true, currentWindow: true});
    if (active.windowId !== win.id || !active.active) return fail('id');
    step = 'c'; const created = await chrome.tabs.create({url: '%s'});
    if (created.windowId !== win.id) return fail('cw');
    step = 'u'; await chrome.tabs.update(active.id, {active: true});
    step = 'm'; await chrome.tabs.move(created.id, {index: 0});
    const [first] = await chrome.tabs.query({index: 0, currentWindow: true});
    if (first.id !== created.id) return fail('mv');
    step = 'r'; await chrome.tabs.remove(created.id);
    const after = await chrome.tabs.query({currentWindow: true});
    if (after.length !== %zu) return fail('rm' + after.length);
    const closed = await chrome.windows.remove(win.id).then(() => 'closed', () => 'kept');
    if (closed !== 'kept') return fail('wr');
    fail('ok');
  })().catch(error => { console.error(step, error.message); chrome.action.setBadgeText({text: 'x' + step}); }))",
      tabs, embedded_test_server()->GetURL("/storage_probe.html?created").spec().c_str(), tabs);
  ASSERT_TRUE(extensions::BackgroundScriptExecutor::ExecuteScriptAsync(work_, extension->id(), script));
  ASSERT_TRUE(base::test::RunUntil([&] {
    const auto badge = Shown(bar, extension->id())->badge;
    return !badge.empty();
  }));
  EXPECT_EQ("ok", Shown(bar, extension->id())->badge);
  // The space is as it was, the window still open.
  EXPECT_EQ(tabs, window_->tab_count("work"));
  EXPECT_EQ(shown, window_->contents("work")->GetLastCommittedURL());
  EXPECT_TRUE(window_->widget()->IsVisible());
}


// windows.create opens its pages as tabs of the profile's Zitter window, and
// windows.update focuses that window: Zitter keeps one window.
IN_PROC_BROWSER_TEST_F(ZitterProfilesBrowserTest, ExtensionWindowsCreateAndUpdateUseZitterWindow) {
  base::ScopedTempDir dir;
  {
    base::ScopedAllowBlockingForTesting allow;
    ASSERT_TRUE(dir.CreateUniqueTempDir());
  }
  const auto extension = LoadTestExtension(work_, WriteTestExtension(dir.GetPath(), "Opener", SK_ColorBLUE, false));
  ASSERT_TRUE(extension);
  auto* bar = window_->extensions_bar();
  NavigateBoth();
  ASSERT_TRUE(window_->Select("work"));
  ASSERT_TRUE(base::test::RunUntil([&] { return Shown(bar, extension->id()).has_value(); }));
  const size_t tabs = window_->tab_count("work");
  const size_t browsers = GlobalBrowserCollection::GetInstance()->GetSize();
  const std::string script = base::StringPrintf(R"(let step = ''; (async () => {
    const fail = text => chrome.action.setBadgeText({text});
    step = 'g'; const win = await chrome.windows.getCurrent();
    step = 'c'; const created = await chrome.windows.create({url: '%s', focused: true});
    if (created.id !== win.id) return fail('cid');
    if (!created.tabs.some(tab => tab.id && tab.windowId === win.id)) return fail('ct');
    step = 'u'; const updated = await chrome.windows.update(win.id, {focused: true});
    if (updated.id !== win.id || updated.type !== 'normal') return fail('uid');
    fail('ok');
  })().catch(error => { console.error(step, error.message); chrome.action.setBadgeText({text: 'x' + step}); }))",
      embedded_test_server()->GetURL("/storage_probe.html?fromwindow").spec().c_str());
  ASSERT_TRUE(extensions::BackgroundScriptExecutor::ExecuteScriptAsync(work_, extension->id(), script));
  ASSERT_TRUE(base::test::RunUntil([&] { return !Shown(bar, extension->id())->badge.empty(); }));
  EXPECT_EQ("ok", Shown(bar, extension->id())->badge);
  EXPECT_EQ(tabs + 1, window_->tab_count("work"));
  EXPECT_EQ("work", window_->active_id());
  EXPECT_NE(std::string::npos, window_->contents("work")->GetVisibleURL().spec().find("fromwindow"));
  base::RunLoop().RunUntilIdle();
  EXPECT_EQ(browsers, GlobalBrowserCollection::GetInstance()->GetSize());
}


// Split View and moves through the tabs API: two tabs of a space pair up in
// Zitter's Split View and separate again, and a tab moves into another space
// of the same profile (the profile's window spans its spaces).
IN_PROC_BROWSER_TEST_F(ZitterProfilesBrowserTest, ExtensionTabsSplitAndMoveAcrossSpaces) {
  base::ScopedTempDir dir;
  {
    base::ScopedAllowBlockingForTesting allow;
    ASSERT_TRUE(dir.CreateUniqueTempDir());
  }
  const auto extension = LoadTestExtension(work_, WriteTestExtension(dir.GetPath(), "Arranger", SK_ColorBLUE, false));
  ASSERT_TRUE(extension);
  auto* bar = window_->extensions_bar();
  NavigateBoth();
  ASSERT_TRUE(window_->Select("work"));
  ASSERT_TRUE(content::NavigateToURL(window_->contents("work"), embedded_test_server()->GetURL("/storage_probe.html?a")));
  ASSERT_TRUE(window_->NavigateFromBar(embedded_test_server()->GetURL("/storage_probe.html?b"), true));
  ASSERT_TRUE(content::WaitForLoadStop(window_->contents("work")));
  ASSERT_TRUE(window_->AddWorkspace("Projekt", "work-profile"));
  ASSERT_TRUE(base::test::RunUntil([&] { return !window_->profiles_busy(); }));
  const std::string project = window_->workspaces().back().id;
  ASSERT_TRUE(window_->Select(project));
  ASSERT_TRUE(content::NavigateToURL(window_->contents(project), embedded_test_server()->GetURL("/storage_probe.html?p")));
  ASSERT_TRUE(window_->Select("work"));
  ASSERT_EQ(2u, window_->tab_count("work"));
  ASSERT_EQ(1u, window_->tab_count(project));
  ASSERT_TRUE(base::test::RunUntil([&] { return Shown(bar, extension->id()).has_value(); }));
  const std::string script = R"(let step = ''; (async () => {
    const fail = text => chrome.action.setBadgeText({text});
    step = 'q'; const all = await chrome.tabs.query({currentWindow: true});
    if (all.length !== 3) return fail('n' + all.length);
    const a = all.find(tab => tab.url.endsWith('?a')), b = all.find(tab => tab.url.endsWith('?b'));
    step = 's'; const split = await chrome.tabs.createSplit([a.id, b.id]);
    const paired = await chrome.tabs.query({splitViewId: split});
    if (paired.length !== 2) return fail('p' + paired.length);
    step = 'u'; await chrome.tabs.unsplit(split);
    if ((await chrome.tabs.get(a.id)).splitViewId !== -1) return fail('sv');
    step = 'm'; await chrome.tabs.move(b.id, {index: 2});
    fail('ok');
  })().catch(error => { console.error(step, error.message); chrome.action.setBadgeText({text: 'x' + step}); }))";
  ASSERT_TRUE(extensions::BackgroundScriptExecutor::ExecuteScriptAsync(work_, extension->id(), script));
  ASSERT_TRUE(base::test::RunUntil([&] { return !Shown(bar, extension->id())->badge.empty(); }));
  EXPECT_EQ("ok", Shown(bar, extension->id())->badge);
  EXPECT_FALSE(window_->split());
  EXPECT_EQ(1u, window_->tab_count("work"));
  EXPECT_EQ(2u, window_->tab_count(project));
  ASSERT_TRUE(window_->Select(project));
  EXPECT_TRUE(window_->contents(project)->GetVisibleURL().spec().ends_with("?p"));
}

// Design: Find & Print. Ctrl+F counts and steps through matches; Esc ends
// the find session.
IN_PROC_BROWSER_TEST_F(ZitterProfilesBrowserTest, FindInPageCountsAndSteps) {
  base::test::ScopedRunLoopTimeout timeout(FROM_HERE, base::Seconds(30));
  ASSERT_TRUE(window_->Select("work"));
  auto* page = window_->contents("work");
  ASSERT_TRUE(content::NavigateToURL(page, GURL("data:text/html,<p>zitter one, zitter two, ZITTER three</p>")));
  auto* shell = window_->shell();
  ASSERT_TRUE(window_->RunShortcut("find"));
  ASSERT_TRUE(shell->find_visible());
  EXPECT_EQ(page, window_->find_page_for_testing());
  auto* field = shell->find_field_for_testing();
  field->InsertOrReplaceText(u"zitter");
  ASSERT_TRUE(base::test::RunUntil([&] { return shell->find_count_for_testing() == TF(u"{} z {}", {u"1", u"3"}); }))
      << shell->find_count_for_testing();
  static_cast<views::View*>(field)->OnKeyPressed(ui::KeyEvent(ui::EventType::kKeyPressed, ui::VKEY_RETURN, ui::EF_NONE));
  ASSERT_TRUE(base::test::RunUntil([&] { return shell->find_count_for_testing() == TF(u"{} z {}", {u"2", u"3"}); }));
  static_cast<views::View*>(field)->OnKeyPressed(ui::KeyEvent(ui::EventType::kKeyPressed, ui::VKEY_RETURN, ui::EF_SHIFT_DOWN));
  ASSERT_TRUE(base::test::RunUntil([&] { return shell->find_count_for_testing() == TF(u"{} z {}", {u"1", u"3"}); }));
  field->SelectAll(false);
  field->InsertOrReplaceText(u"kwarki");
  ASSERT_TRUE(base::test::RunUntil([&] { return shell->find_count_for_testing() == T(u"Brak wyników"); }));
  // Ctrl+F again keeps the bar and its text.
  ASSERT_TRUE(window_->RunShortcut("find"));
  EXPECT_EQ(u"kwarki", field->GetText());
  ASSERT_TRUE(static_cast<ui::AcceleratorTarget*>(window_.get())->AcceleratorPressed(ui::Accelerator(ui::VKEY_ESCAPE, ui::EF_NONE)));
  EXPECT_FALSE(shell->find_visible());
  EXPECT_EQ(nullptr, window_->find_page_for_testing());
  EXPECT_FALSE(find_in_page::FindTabHelper::FromWebContents(page)->find_ui_active());
}

// Design: Find & Print. Ctrl+P previews every page in the sandboxed printing
// service, counts the chosen sheets and saves the chosen pages as a PDF.
IN_PROC_BROWSER_TEST_F(ZitterProfilesBrowserTest, PrintSheetPreviewsAndSavesPdf) {
  base::test::ScopedRunLoopTimeout timeout(FROM_HERE, base::Seconds(60));
  auto* factory = ui::FakeSelectFileDialog::RegisterFactory();
  factory->SetOpenCallback(base::DoNothing());
  ASSERT_TRUE(window_->Select("work"));
  auto* page = window_->contents("work");
  ASSERT_TRUE(content::NavigateToURL(page, GURL("data:text/html,<title>Probe</title><div style='height:2400px'>first</div><p>last</p>")));
  auto* shell = window_->shell();
  ASSERT_TRUE(window_->RunShortcut("print"));
  ASSERT_TRUE(shell->print_visible());
  ASSERT_TRUE(base::test::RunUntil([&] { return shell->print_ready_for_testing(); }));
  const size_t pages = shell->print_preview_pages_for_testing();
  EXPECT_GE(pages, 2u);
  // Save as PDF comes after the printers; a range picks one sheet.
  shell->PrintChooseForTesting(1000, 2, u"2", false);
  ASSERT_TRUE(base::test::RunUntil([&] { return shell->print_ready_for_testing(); }));
  EXPECT_EQ(TF(u"{} arkusz", {u"1"}), shell->print_sheets_for_testing());
  shell->PrintChooseForTesting(1000, 2, u"9-12", false);
  EXPECT_FALSE(shell->print_ready_for_testing());
  shell->PrintChooseForTesting(1000, 0, u"", true);
  ASSERT_TRUE(base::test::RunUntil([&] { return shell->print_ready_for_testing(); }));
  EXPECT_GE(shell->print_preview_pages_for_testing(), pages);  // Landscape pages are shorter.
  shell->PrintNowForTesting();
  ASSERT_TRUE(base::test::RunUntil([&] { return factory->GetLastDialog() != nullptr; }));
  base::ScopedTempDir directory;
  {
    base::ScopedAllowBlockingForTesting allow;
    ASSERT_TRUE(directory.CreateUniqueTempDir());
  }
  const auto path = directory.GetPath().AppendASCII("probe.pdf");
  ASSERT_TRUE(factory->GetLastDialog()->CallFileSelected(path, "pdf"));
  ASSERT_TRUE(base::test::RunUntil([&] { return !shell->print_visible(); }));
  base::ScopedAllowBlockingForTesting allow;
  std::string pdf;
  ASSERT_TRUE(base::test::RunUntil([&] { return base::ReadFileToString(path, &pdf) && !pdf.empty(); }));
  EXPECT_TRUE(pdf.starts_with("%PDF-"));
  ui::SelectFileDialog::SetFactory(nullptr);
}

// Zitter starts with Chrome's Print Preview off (Runtime::PreBrowserStart).
class ZitterPrintBrowserTest : public ZitterProfilesBrowserTest {
 public:
  void SetUpCommandLine(base::CommandLine* command_line) override {
    ZitterProfilesBrowserTest::SetUpCommandLine(command_line);
    command_line->AppendSwitch(switches::kDisablePrintPreview);
  }
};

// A page's own window.print() opens Zitter's sheet, not the system dialog;
// a page in the background opens nothing.
IN_PROC_BROWSER_TEST_F(ZitterPrintBrowserTest, PagePrintOpensTheSheet) {
  base::test::ScopedRunLoopTimeout timeout(FROM_HERE, base::Seconds(30));
  ASSERT_TRUE(window_->Select("work"));
  auto* page = window_->contents("work");
  ASSERT_TRUE(content::NavigateToURL(page, GURL("data:text/html,<p>print me</p>")));
  auto* shell = window_->shell();
  ASSERT_TRUE(content::ExecJs(page, "window.print(); true"));
  ASSERT_TRUE(base::test::RunUntil([&] { return shell->print_visible(); }));
  ASSERT_TRUE(base::test::RunUntil([&] { return shell->print_ready_for_testing(); }));
  EXPECT_EQ(1u, shell->print_preview_pages_for_testing());
  shell->HidePrint();
  ASSERT_TRUE(window_->Select("personal"));
  ASSERT_TRUE(content::NavigateToURL(window_->contents("personal"), GURL("data:text/html,<p>here</p>")));
  ASSERT_TRUE(content::ExecJs(page, "window.print(); true"));
  base::RunLoop idle;
  base::SingleThreadTaskRunner::GetCurrentDefault()->PostDelayedTask(FROM_HERE, idle.QuitClosure(), base::Seconds(1));
  idle.Run();
  EXPECT_FALSE(shell->print_visible());
}

// Design: Prośba o dostęp — a notification request is a quiet card under the
// address pill that folds into a struck-through bell and comes back from it.
IN_PROC_BROWSER_TEST_F(ZitterProfilesBrowserTest, NotificationRequestCardFoldsIntoPill) {
  base::test::ScopedRunLoopTimeout timeout(FROM_HERE, base::Seconds(30));
  auto* page = window_->contents("work");
  const auto url = embedded_test_server()->GetURL("localhost", "/login_probe.html");
  ASSERT_TRUE(content::NavigateToURL(page, url));
  auto* access = PageMediaAccess::FromWebContents(page);
  ASSERT_TRUE(access);
  ASSERT_TRUE(content::ExecJs(page, "window.answer = 'waiting'; Notification.requestPermission().then(a => window.answer = a); void 0;"));
  ASSERT_TRUE(base::test::RunUntil([&] { return access->permission_prompt() && access->permission_prompt()->IsVisible(); }));
  auto* card = access->permission_prompt();
  auto* shell = window_->shell();
  EXPECT_EQ(ui::mojom::ModalType::kNone, card->widget_delegate()->GetModalType());
  EXPECT_FALSE(card->IsActive());
  EXPECT_EQ(1, access->prompt_offer().kind);
  EXPECT_EQ(base::UTF8ToUTF16("localhost:" + std::string(url.port())), access->prompt_offer().site);
  ASSERT_TRUE(shell->permission_chip_for_testing());
  EXPECT_TRUE(shell->permission_chip_for_testing()->GetVisible());
  // Ignored, it folds: the page keeps going and the pill explains what happened.
  access->FoldPromptForTesting();
  EXPECT_FALSE(card->IsVisible());
  EXPECT_TRUE(access->prompt_offer().folded);
  EXPECT_NE(shell->permission_chip_for_testing()->GetRenderedTooltipText(gfx::Point()).find(u"Zablokowane po cichu"), std::u16string::npos);
  EXPECT_EQ("waiting", content::EvalJs(page, "window.answer"));
  access->ReopenPrompt();
  EXPECT_TRUE(card->IsVisible());
  access->DecidePromptForTesting(1);
  ASSERT_TRUE(base::test::RunUntil([&] { return content::EvalJs(page, "window.answer").ExtractString() == "granted"; }));
  EXPECT_FALSE(access->permission_prompt());
  EXPECT_FALSE(shell->permission_chip_for_testing()->GetVisible());
  EXPECT_EQ(CONTENT_SETTING_ALLOW, HostContentSettingsMapFactory::GetForProfile(work_)->GetContentSetting(url, url, ContentSettingsType::NOTIFICATIONS));
}

// Design: Zitter panel witryny — every permission the site has a rule for, each
// changed from its row's menu; the data page lists cookies and clears the site.
IN_PROC_BROWSER_TEST_F(ZitterProfilesBrowserTest, SitePanelChangesPermissionsAndClearsSite) {
  base::test::ScopedRunLoopTimeout timeout(FROM_HERE, base::Seconds(30));
  auto* page = window_->contents("work");
  const auto url = embedded_test_server()->GetURL("localhost", "/login_probe.html");
  ASSERT_TRUE(content::NavigateToURL(page, url));
  auto* settings = HostContentSettingsMapFactory::GetForProfile(work_);
  settings->SetContentSettingDefaultScope(url, url, ContentSettingsType::NOTIFICATIONS, CONTENT_SETTING_ALLOW);
  // A kind Zitter's old list missed: it shows, so it can be taken back.
  settings->SetContentSettingDefaultScope(url, url, ContentSettingsType::LOCAL_NETWORK_ACCESS, CONTENT_SETTING_ALLOW);
  {
    const auto summary = ReadSitePermissions(work_, url);
    ASSERT_EQ(2u, summary.permissions.size());
    EXPECT_TRUE(std::ranges::any_of(summary.permissions, [](const auto& p) { return p.key == "local-network-access" && p.setting == 1; }));
  }
  auto* shell = window_->shell();
  shell->ShowSidebar();
  window_->ShowSitePanel();
  ASSERT_TRUE(shell->site_panel_for_testing());
  EXPECT_TRUE(shell->site_panel_for_testing()->IsVisible());
  ASSERT_EQ(2u, shell->site_rows_for_testing());
  const auto notifications_row = [&] {
    const auto summary = ReadSitePermissions(work_, url);
    for (size_t i = 0; i < summary.permissions.size(); ++i) if (summary.permissions[i].key == "notifications") return i;
    return summary.permissions.size();
  };
  // The row's menu: Blokuj, then Pytaj (the default, so the rule goes).
  shell->SetSitePermissionForTesting(notifications_row(), 2);
  EXPECT_EQ(CONTENT_SETTING_BLOCK, settings->GetContentSetting(url, url, ContentSettingsType::NOTIFICATIONS));
  shell->SetSitePermissionForTesting(notifications_row(), 3);
  EXPECT_EQ(CONTENT_SETTING_ASK, settings->GetContentSetting(url, url, ContentSettingsType::NOTIFICATIONS));
  ASSERT_TRUE(base::test::RunUntil([&] { return shell->site_rows_for_testing() == 1u; }));
  // "Zapomnij ustawienia tej witryny" drops what is left.
  shell->SetSitePermissionForTesting(0, 10);
  EXPECT_TRUE(ReadSitePermissions(work_, url).permissions.empty());
  ASSERT_TRUE(base::test::RunUntil([&] { return shell->site_rows_for_testing() == 0u; }));
  // The data page lists the cookie; clearing reloads and keeps another site's.
  ASSERT_TRUE(content::ExecJs(page, "document.cookie = 'zitter=1; max-age=3600'"));
  const auto other = embedded_test_server()->GetURL("127.0.0.1", "/login_probe.html");
  auto* store = work_->GetDefaultStoragePartition()->GetCookieManagerForBrowserProcess();
  base::test::TestFuture<net::CookieAccessResult> set;
  store->SetCanonicalCookie(*net::CanonicalCookie::CreateForTesting(other, "keep=1", base::Time::Now(), net::CookieSourceType::kHTTP), other, net::CookieOptions::MakeAllInclusive(), set.GetCallback());
  ASSERT_TRUE(set.Get().status.IsInclude());
  base::test::TestFuture<const SiteDataFacts&> measured;
  MeasureSiteData(work_, url, base::BindLambdaForTesting([&](const SiteDataFacts& facts) {
    if (facts.cookies >= 0 && facts.bytes >= 0 && facts.visits >= 0 && !measured.IsReady()) measured.SetValue(facts);
  }));
  ASSERT_EQ(1u, measured.Get().cookie_list.size());
  EXPECT_EQ("zitter", measured.Get().cookie_list[0].name);
  window_->ShowSitePanel();
  shell->ShowSiteData(true);
  ASSERT_TRUE(base::test::RunUntil([&] { return shell->site_page_for_testing() == 1; }));
  content::TestNavigationObserver reload(page);
  shell->ClearSiteNow();
  reload.Wait();
  EXPECT_FALSE(shell->site_panel_for_testing());
  EXPECT_EQ("", content::EvalJs(page, "document.cookie"));
  base::test::TestFuture<const net::CookieList&> kept;
  store->GetCookieList(other, net::CookieOptions::MakeAllInclusive(), net::CookiePartitionKeyCollection(), base::BindOnce([](base::OnceCallback<void(const net::CookieList&)> done, const net::CookieAccessResultList& list, const net::CookieAccessResultList&) {
    std::move(done).Run(net::cookie_util::StripAccessResults(list));
  }, kept.GetCallback()));
  ASSERT_EQ(1u, kept.Get().size());
}

